    async def gift_inventory(owner_id: int, limit: int | None, offset: int, *, public: bool, viewer_id: int | None = None) -> dict[str, Any]:
        """The same paginated inventory for the owner and for a profile visitor."""
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            visible = " AND profile_hidden=0" if public else ""
            cur = await db.execute(
                "SELECT COUNT(*) FROM user_gifts WHERE owner_telegram_id=?" + visible,
                (owner_id,),
            )
            total = int((await cur.fetchone())[0] or 0)
            query = f"""SELECT id,serial_number,gift_id,telegram_gift_id,gift_name,gift_emoji,
                          telegram_gift_metadata_json,acquired_at,upgrade_level,attributes_json,
                          purchase_asset,purchase_price,profile_pinned,profile_worn,profile_hidden,
                          (SELECT p.supply FROM telegram_gift_prices p WHERE p.gift_id=user_gifts.telegram_gift_id) AS shop_supply,
                          (SELECT MAX(0, p.supply-p.sold) FROM telegram_gift_prices p WHERE p.gift_id=user_gifts.telegram_gift_id) AS shop_remaining,
                          EXISTS(SELECT 1 FROM gift_market_listings l
                                 WHERE l.serial_number=user_gifts.serial_number
                                   AND l.status='active') AS is_listed,
                          EXISTS(SELECT 1 FROM gift_collectible_auctions a
                                 WHERE a.serial_number=user_gifts.serial_number
                                   AND a.status='active') AS is_auctioned,
                          (
                              EXISTS(SELECT 1 FROM telegram_gift_catalog c
                                     WHERE c.gift_id=user_gifts.telegram_gift_id
                                       AND (COALESCE(c.sticker_file_id,'')<>''
                                            OR COALESCE(c.sticker_thumbnail_file_id,'')<>''))
                              OR EXISTS(SELECT 1 FROM telegram_mtproto_gift_catalog m
                                        WHERE m.gift_id=user_gifts.telegram_gift_id
                                          AND COALESCE(m.sticker_document_id,'')<>'')
                          ) AS sticker_available,
                          EXISTS(SELECT 1 FROM telegram_auction_gift_registry r
                                 WHERE r.gift_id=user_gifts.telegram_gift_id) AS auction_eligible,
                          (SELECT n.unique_num FROM gift_unique_numbers n
                            WHERE n.serial_number=user_gifts.serial_number) AS unique_num
                   FROM user_gifts WHERE owner_telegram_id=?{visible}
                   ORDER BY profile_pinned DESC, profile_order IS NOT NULL, profile_order ASC, id DESC"""
            query_params: tuple[Any, ...] = (owner_id,)
            if limit is not None:
                query += " LIMIT ? OFFSET ?"
                query_params += (limit + 1, offset)
            elif offset:
                query += " LIMIT -1 OFFSET ?"
                query_params += (offset,)
            cur = await db.execute(query, query_params)
            rows = await cur.fetchall()
        if limit is None:
            has_more = False
        else:
            has_more = len(rows) > limit
            rows = rows[:limit]
        gifts = []
        metadata_by_id: dict[str, dict[str, Any] | None] = {}
        async with aiosqlite.connect(db_path()) as gift_db:
            gift_db.row_factory = aiosqlite.Row
            # Batch provenance for the whole page instead of querying each gift and sender.
            acquisitions: dict[str, Any] = {}
            serials = [str(row["serial_number"]) for row in rows]
            for start in range(0, len(serials), 400):
                chunk = serials[start:start + 400]
                placeholders = ",".join("?" for _ in chunk)
                cur = await gift_db.execute(
                    f"""SELECT t.serial_number,t.event_type,t.from_telegram_id,t.created_at,
                               t.message_id,a.telegram_id AS sender_account_id,
                               a.username,a.display_name,a.avatar_media_id,
                               m.body,mg.attributes_json AS message_attributes
                        FROM gift_transactions t
                        JOIN (SELECT MAX(id) AS id FROM gift_transactions
                              WHERE to_telegram_id=? AND serial_number IN ({placeholders})
                                AND event_type IN ('purchase','transfer','chat_send','market_sale','auction_sale')
                              GROUP BY serial_number) latest ON latest.id=t.id
                        LEFT JOIN accounts a ON a.telegram_id=CASE WHEN t.event_type='purchase'
                            THEN t.to_telegram_id ELSE t.from_telegram_id END AND a.is_banned=0
                        LEFT JOIN message_gifts mg ON mg.serial_number=t.serial_number AND mg.message_id=COALESCE(
                            t.message_id, CASE WHEN t.event_type IN ('purchase','chat_send') THEN
                              (SELECT m2.id FROM message_gifts mg2 JOIN messages m2 ON m2.id=mg2.message_id
                               WHERE mg2.serial_number=t.serial_number
                                 AND m2.sender_telegram_id=CASE WHEN t.event_type='purchase'
                                     THEN t.to_telegram_id ELSE t.from_telegram_id END
                                 AND m2.recipient_telegram_id=t.to_telegram_id
                                 AND m2.created_at=t.created_at ORDER BY m2.id DESC LIMIT 1)
                            END)
                        LEFT JOIN messages m ON m.id=mg.message_id""",
                    (owner_id, *chunk),
                )
                acquisitions.update({str(row["serial_number"]): row for row in await cur.fetchall()})
            documents_by_id: dict[str, dict[str, list[dict[str, Any]]]] = {}
            for row in rows:
                item = dict(row)
                raw_attributes = item.pop("attributes_json", "{}")
                try:
                    attributes = json.loads(raw_attributes or "{}")
                except (TypeError, ValueError):
                    attributes = {}
                item["attributes"] = attributes if isinstance(attributes, dict) else {}
                raw_snapshot = item.pop("telegram_gift_metadata_json", "{}")
                try:
                    snapshot = json.loads(raw_snapshot or "{}")
                except (TypeError, ValueError):
                    snapshot = {}
                snapshot = snapshot if isinstance(snapshot, dict) else {}
                gift_id = str(item.get("telegram_gift_id") or "")
                if gift_id not in metadata_by_id:
                    metadata_by_id[gift_id] = await _telegram_gift_metadata(gift_db, gift_id)
                telegram_gift = _merge_telegram_gift_metadata(metadata_by_id[gift_id], snapshot)
                item["telegram_gift"] = telegram_gift
                # Older upgrades were rolled before Telegram's attribute set was known, so
                # their traits carry no document id: the native card then cannot play the
                # official model and pattern. The id is restored from the local catalog and
                # stored back once, so every later read has it straight away.
                collectible = gift_upgrades.traits_of(item["attributes"])
                if gift_upgrades.is_current_traits(collectible) and any(
                    isinstance(collectible.get(key), dict)
                    and not int((collectible.get(key) or {}).get("document_id") or 0)
                    for key in ("model", "pattern")
                ):
                    if gift_id not in documents_by_id:
                        documents_by_id[gift_id] = await _gift_attribute_documents(gift_db, gift_id)
                    documents = documents_by_id[gift_id]
                    if not documents:
                        # Telegram was never asked about this gift (it was upgraded before the
                        # catalog reached this server): the answer is fetched for the next read.
                        schedule_attribute_sync(gift_id)
                    _, pool = _collectible_trait_pool(
                        gift_id,
                        telegram_gift.get("title") if telegram_gift else item.get("gift_name"),
                    )
                    if _enrich_traits_documents(collectible, pool, documents, gift_id=gift_id):
                        await gift_db.execute(
                            "UPDATE user_gifts SET attributes_json=? WHERE id=?",
                            (
                                json.dumps(
                                    item["attributes"], ensure_ascii=False,
                                    separators=(",", ":"),
                                ),
                                int(item.get("id") or 0),
                            ),
                        )
                        await gift_db.commit()
                # A pinned local artwork pack can supply the exact named model of older
                # Heart Locket upgrades even when Telegram only provides a preview sample.
                # This synthetic document ID exists only in the response, never in the DB;
                # a later authoritative Telegram match can still take precedence.
                if isinstance(collectible, dict):
                    model_trait = collectible.get("model")
                    model_name = model_trait.get("name") if isinstance(model_trait, dict) else model_trait
                    if not isinstance(model_trait, dict) or not int(model_trait.get("document_id") or 0):
                        fallback_model = gift_model_fallbacks.model_for_name(gift_id, model_name)
                        fallback_id = (fallback_model["document_id"] if fallback_model else
                                       gift_model_fallbacks.remote_document_for_name(gift_id, model_name))
                        if fallback_id:
                            if not isinstance(model_trait, dict):
                                model_trait = {"name": model_name}
                                collectible["model"] = model_trait
                            model_trait["document_id"] = fallback_id
                if telegram_gift and str(telegram_gift.get("title") or "").strip():
                    item["gift_name"] = str(telegram_gift["title"]).strip()
                item["gift_emoji"] = (
                    str(item.get("gift_emoji") or "").strip()
                    or (str(telegram_gift.get("emoji") or "").strip() if telegram_gift else "")
                )
                item["can_upgrade"] = bool(
                    _gift_supports_upgrade(gift_id, metadata_by_id[gift_id])
                    and int(item.get("upgrade_level") or 0) == 0
                    and not collectible
                )
                item["waysgram_can_upgrade"] = bool(
                    telegram_gift and telegram_gift.get("can_upgrade")
                )
                # WaysGram charges a fixed price for an upgrade, so the client always shows
                # the same amount instead of the Telegram catalog value.
                item["upgrade_star_count"] = UPGRADE_PRICE_STARS
                if telegram_gift:
                    item["telegram_gift"] = {
                        **telegram_gift,
                        "upgrade_star_count": UPGRADE_PRICE_STARS,
                    }
                item["unique_num"] = int(item.get("unique_num") or 0)
                item["sticker_available"] = bool(
                    item.get("sticker_available")
                    or (telegram_gift and telegram_gift.get("sticker_available"))
                )
                item["sticker_url"] = (
                    telegram_gift.get("sticker", {}).get("url", "")
                    if telegram_gift and item["sticker_available"]
                    else ""
                )
                item["owner_id"] = owner_id
                # The current acquisition is authoritative even when an older chat message
                # survived a subsequent transfer or resale. Never publish provenance on NFTs.
                item["sender_id"] = None
                item["gift_message"] = ""
                if int(item.get("upgrade_level") or 0) == 0 and not collectible:
                    acquisition = acquisitions.get(str(item["serial_number"]))
                    sender = int(acquisition["from_telegram_id"] or 0) if acquisition else 0
                    if acquisition and acquisition["event_type"] == "purchase":
                        sender = owner_id
                    if sender:
                        try:
                            message_attributes = json.loads(acquisition["message_attributes"] or "{}")
                        except (TypeError, ValueError):
                            message_attributes = {}
                        hidden = isinstance(message_attributes, dict) and message_attributes.get("hide_name") is True
                        if not hidden:
                            item["sender_id"] = sender
                            if acquisition["sender_account_id"]:
                                item["sender"] = {
                                    "id": int(acquisition["sender_account_id"]),
                                    "username": acquisition["username"],
                                    "display_name": acquisition["display_name"],
                                    "avatar_media_id": acquisition["avatar_media_id"] if await privacy_allows(gift_db, sender, viewer_id if viewer_id is not None else owner_id, "avatar") else "",
                                }
                        text = str(acquisition["body"] or "").strip()
                        if text != "Подарок WaysGram":
                            item["gift_message"] = text
                purchase_asset = str(item.pop("purchase_asset", "") or "stars").strip()
                if purchase_asset not in {"stars", "grams"}:
                    purchase_asset = "stars"
                purchase_price = int(item.pop("purchase_price", 0) or 0)
                sell_refund = purchase_price * SELL_REFUND_PERCENT // 100
                sellable_until = int(item.get("acquired_at") or 0) + SELL_WINDOW_SECONDS
                item["purchase_asset"] = purchase_asset
                item["purchase_price"] = purchase_price
                item["sell_refund"] = sell_refund
                item["sell_refund_asset"] = purchase_asset
                item["sellable_until"] = sellable_until
                item["sellable"] = bool(
                    sell_refund > 0
                    and not int(item.get("is_listed") or 0)
                    and not int(item.get("is_auctioned") or 0)
                    and int(time.time()) < sellable_until
                )
                if public:
                    # Prices, refundable value and the sale window are owner-only data.
                    for field in ("purchase_asset", "purchase_price", "sell_refund", "sell_refund_asset", "sellable_until", "sellable"):
                        item.pop(field, None)
                gifts.append(item)
        return {
            "gifts": gifts,
            "total": total,
            "limit": limit,
            "offset": offset,
            "has_more": has_more,
            "next_offset": offset + len(gifts) if has_more else None,
        }

    @router.put("/api/me/gifts/{serial_number}/pin")
    async def set_gift_profile_pin(
        serial_number: str, payload: dict[str, Any], authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        uid = int((await current_user(authorization))["telegram_id"])
        serial = serial_number.strip().upper()
        pinned = payload.get("pinned")
        if not GIFT_SERIAL_RE.fullmatch(serial) or type(pinned) is not bool:
            raise HTTPException(status_code=400, detail="Некорректные параметры закрепления")
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            cur = await db.execute(
                "SELECT id,upgrade_level,attributes_json,profile_pinned FROM user_gifts WHERE serial_number=? AND owner_telegram_id=?",
                (serial, uid),
            )
            gift = await cur.fetchone()
            if gift is None:
                raise HTTPException(status_code=404, detail="Подарок не найден")
            try:
                attrs = json.loads(gift[2] or "{}")
            except (TypeError, ValueError):
                attrs = {}
            if pinned and not (int(gift[1] or 0) > 0 or _has_collectible_traits(attrs)):
                raise HTTPException(status_code=409, detail="Можно закрепить только коллекционный подарок")
            if pinned and not gift[3]:
                cur = await db.execute("SELECT COUNT(*) FROM user_gifts WHERE owner_telegram_id=? AND profile_pinned=1", (uid,))
                if int((await cur.fetchone())[0]) >= 6:
                    raise HTTPException(status_code=409, detail="Можно закрепить до шести подарков. Сначала открепите один из них.")
            await db.execute("UPDATE user_gifts SET profile_pinned=?,profile_hidden=CASE WHEN ? THEN 0 ELSE profile_hidden END WHERE id=?", (int(pinned), pinned, gift[0]))
            await db.commit()
        return {"serial_number": serial, "pinned": pinned}

    @router.put("/api/me/gifts/{serial_number}/visibility")
    async def set_gift_visibility(serial_number: str, payload: dict[str, Any], authorization: str | None = Header(default=None)):
        uid = int((await current_user(authorization))["telegram_id"])
        visible = payload.get("visible")
        if type(visible) is not bool:
            raise HTTPException(400, "GIFT_VISIBILITY_INVALID")
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            cur = await db.execute("""UPDATE user_gifts SET profile_hidden=?,
                profile_pinned=CASE WHEN ? THEN profile_pinned ELSE 0 END,
                profile_worn=CASE WHEN ? THEN profile_worn ELSE 0 END
                WHERE serial_number=? AND owner_telegram_id=?""", (not visible, visible, visible, serial_number.upper(), uid))
            if cur.rowcount != 1:
                raise HTTPException(404, "GIFT_NOT_FOUND")
            await db.commit()
        return {"visible": visible}

    gift_receive_types = ("regular", "collectible")

    async def gift_receive_rules(db: Any, uid: int) -> list[str]:
        cur = await db.execute("SELECT rules FROM account_profile_privacy WHERE telegram_id=? AND setting='gift-receive'", (uid,))
        row = await cur.fetchone()
        return json.loads(row[0]) if row else list(gift_receive_types)

    @router.get("/api/me/gift-receive")
    async def get_gift_receive(authorization: str | None = Header(default=None)):
        uid = int((await current_user(authorization))["telegram_id"])
        async with aiosqlite.connect(db_path()) as db:
            return {"allowed_types": await gift_receive_rules(db, uid)}

    @router.put("/api/me/gift-receive")
    async def set_gift_receive(payload: dict[str, Any], authorization: str | None = Header(default=None)):
        uid = int((await current_user(authorization))["telegram_id"])
        allowed = payload.get("allowed_types")
        if not isinstance(allowed, list) or len(allowed) > len(gift_receive_types) or any(x not in gift_receive_types for x in allowed):
            raise HTTPException(400, "GIFT_TYPES_INVALID")
        allowed = [kind for kind in gift_receive_types if kind in allowed]
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("""INSERT INTO account_profile_privacy VALUES(?,'gift-receive',?)
                ON CONFLICT(telegram_id,setting) DO UPDATE SET rules=excluded.rules""", (uid, json.dumps(allowed)))
            await db.commit()
        return {"allowed_types": allowed}

    async def require_gift_type(db: Any, recipient: int, upgrade_level: int = 0, attributes_json: str | None = None) -> None:
        try:
            attributes = json.loads(attributes_json or "{}")
        except (ValueError, TypeError):
            attributes = {}
        kind = "collectible" if int(upgrade_level or 0) > 0 or _has_collectible_traits(attributes) else "regular"
        if kind not in await gift_receive_rules(db, recipient):
            raise HTTPException(403, "GIFT_TYPE_FORBIDDEN")

    async def require_gift_delivery_allowed(db: Any, sender: int, recipient: int) -> None:
        if sender == recipient:
            return
        cur = await db.execute(
            """SELECT 1 FROM blocked_users
               WHERE (owner_telegram_id=? AND blocked_telegram_id=?)
                  OR (owner_telegram_id=? AND blocked_telegram_id=?)""",
            (sender, recipient, recipient, sender),
        )
        if await cur.fetchone():
            raise HTTPException(403, "Нельзя отправить подарок: пользователь находится в чёрном списке")
        # «Кто может присылать мне подарки»: все / только контакты / никто.
        if not await privacy_allows(db, recipient, sender, "gifts"):
            raise HTTPException(403, "GIFT_PRIVACY_FORBIDDEN")

    async def apply_gift_autosave(db: Any, serial: str, owner: int, sender: int) -> None:
        visible = await privacy_allows(db, owner, sender, "gift-autosave")
        await db.execute("UPDATE user_gifts SET profile_hidden=? WHERE serial_number=? AND owner_telegram_id=?",
                         (not visible, serial, owner))

    @router.put("/api/me/gifts/order")
    async def reorder_my_gifts(request: Request, authorization: str | None = Header(default=None)) -> dict[str, Any]:
        user = await current_user(authorization)
        try:
            body = await request.json()
        except ValueError:
            raise HTTPException(status_code=400, detail="Некорректный порядок подарков")
        expected = body.get("expected") if isinstance(body, dict) else None
        order = body.get("order") if isinstance(body, dict) else None
        if (not isinstance(expected, list) or not isinstance(order, list)
                or len(order) > 10000 or len(expected) != len(order)
                or any(type(x) is not int or x <= 0 for x in expected + order)
                or len(set(expected)) != len(expected) or set(expected) != set(order)):
            raise HTTPException(status_code=400, detail="Некорректный порядок подарков")
        uid = int(user["telegram_id"])
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            cursor = await db.execute(
                """SELECT id,profile_pinned FROM user_gifts WHERE owner_telegram_id=?
                   ORDER BY profile_pinned DESC, profile_order IS NOT NULL, profile_order ASC, id DESC""", (uid,))
            rows = await cursor.fetchall()
            current = [int(row[0]) for row in rows]
            if current != expected:
                await db.rollback()
                raise HTTPException(status_code=409, detail="Список подарков изменился; обновите его")
            pinned_ids = {int(row[0]) for row in rows if row[1]}
            if set(order[:len(pinned_ids)]) != pinned_ids:
                raise HTTPException(status_code=409, detail="Закреплённые подарки должны оставаться сверху")
            await db.executemany(
                "UPDATE user_gifts SET profile_order=? WHERE id=? AND owner_telegram_id=?",
                [(i, gift_id, uid) for i, gift_id in enumerate(order)],
            )
            await db.commit()
        return {"ok": True}

