    @router.get("/api/users")
    async def search_users(
        q: str = Query(default="", max_length=64),
        authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        uid = int((await current_user(authorization))["telegram_id"])
        q = q.strip().lstrip("@")
        if not q:
            return {"users": []}
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            if q.isdigit():
                cur = await db.execute(
                    """SELECT telegram_id AS id,username,display_name,avatar_media_id FROM accounts
                       WHERE telegram_id=? LIMIT 30""",
                    (int(q),),
                )
            else:
                cur = await db.execute(
                    """SELECT telegram_id AS id,username,display_name,avatar_media_id FROM accounts
                       WHERE username LIKE ? OR display_name LIKE ?
                       ORDER BY CASE WHEN username = ? COLLATE NOCASE THEN 0 ELSE 1 END, telegram_id DESC LIMIT 30""",
                    (f"%{q}%", f"%{q}%", q),
                )
            rows = await avatar_visible_rows(db, await cur.fetchall(), uid)
        users = []
        for row in rows:
            item = dict(row)
            item["labels"] = await entity_labels("account", int(item["id"]))
            users.append(item)
        return {"users": users}

    @router.post("/api/contacts/resolve-phone")
    async def resolve_contact_phone(payload: dict[str, Any], authorization: str | None = Header(default=None)):
        uid = int((await current_user(authorization))["telegram_id"])
        phone = payload.get("phone")
        if not isinstance(phone, str) or not is_virtual_number(phone if phone.startswith("+") else "+" + phone):
            raise HTTPException(400, "PHONE_NUMBER_INVALID")
        phone = "+" + phone.lstrip("+")
        minute = int(time.time()) // 60
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute("""INSERT INTO phone_lookup_limits(telegram_id,minute,attempts) VALUES(?,?,1)
                ON CONFLICT(telegram_id) DO UPDATE SET
                    attempts=CASE WHEN minute=excluded.minute THEN attempts+1 ELSE 1 END,
                    minute=excluded.minute
                WHERE minute<>excluded.minute OR attempts<20""", (uid, minute))
            allowed = cur.rowcount == 1
            await db.commit()
            if not allowed:
                raise HTTPException(429, "FLOOD_WAIT_60", headers={"Retry-After": "60"})
            await db.execute("BEGIN")
            cur = await db.execute("""SELECT telegram_id AS id,username,display_name,avatar_media_id
                FROM accounts WHERE is_banned=0 AND telegram_id IN (
                    SELECT telegram_id FROM accounts WHERE virtual_number=?
                    UNION SELECT telegram_id FROM numbers WHERE number=?
                ) LIMIT 2""", (phone, phone))
            matches = await cur.fetchall()
            if len(matches) != 1 or not await privacy_allows(db, int(matches[0]["id"]), uid, "find-by-phone"):
                raise HTTPException(404, "PHONE_NOT_OCCUPIED")
            return (await avatar_visible_rows(db, matches, uid))[0]

    @router.get("/api/contacts")
    async def list_contacts(authorization: str | None = Header(default=None)) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute(
                """SELECT a.telegram_id AS id,a.username,a.display_name,a.avatar_media_id,a.bio,c.created_at,
                          COALESCE(n.note,'') AS note
                   FROM contacts c JOIN accounts a ON a.telegram_id=c.contact_telegram_id
                   LEFT JOIN contact_notes n
                     ON n.owner_telegram_id=c.owner_telegram_id AND n.contact_telegram_id=c.contact_telegram_id
                   WHERE c.owner_telegram_id=? AND a.is_banned=0
                   ORDER BY lower(a.display_name),lower(a.username),a.telegram_id""",
                (uid,),
            )
            rows = await avatar_visible_rows(db, await cur.fetchall(), uid)
        contacts = []
        for row in rows:
            item = dict(row)
            item["labels"] = await entity_labels("account", int(item["id"]))
            contacts.append(item)
        return {"contacts": contacts, "count": len(contacts)}

    @router.post("/api/contacts", status_code=201)
    async def add_contact(
        payload: dict[str, Any],
        authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        value = payload.get("user_id")
        if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
            raise HTTPException(status_code=400, detail="Укажите корректный ID пользователя")
        if value == uid:
            raise HTTPException(status_code=400, detail="Нельзя добавить себя в контакты")
        now = int(time.time())
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute(
                "SELECT telegram_id AS id,username,display_name,avatar_media_id,bio FROM accounts WHERE telegram_id=? AND is_banned=0",
                (value,),
            )
            contact = await cur.fetchone()
            if contact is None:
                raise HTTPException(status_code=404, detail="Пользователь не найден")
            cur = await db.execute(
                """INSERT OR IGNORE INTO contacts(owner_telegram_id,contact_telegram_id,created_at)
                   VALUES(?,?,?)""",
                (uid, value, now),
            )
            added = cur.rowcount == 1
            contact = (await avatar_visible_rows(db, [contact], uid))[0]
            await db.commit()
        return {
            "status": "added" if added else "already_exists",
            "contact": dict(contact),
        }

    @router.delete("/api/contacts/{user_id}")
    async def remove_contact(
        user_id: int,
        authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        async with aiosqlite.connect(db_path()) as db:
            owner_id = int(user["telegram_id"])
            cur = await db.execute(
                "DELETE FROM contacts WHERE owner_telegram_id=? AND contact_telegram_id=?",
                (owner_id, user_id),
            )
            if cur.rowcount != 1:
                raise HTTPException(status_code=404, detail="Контакт не найден")
            await db.execute(
                "DELETE FROM contact_notes WHERE owner_telegram_id=? AND contact_telegram_id=?",
                (owner_id, user_id),
            )
            await db.commit()
        return {"status": "removed", "user_id": user_id}

    @router.put("/api/contacts/{user_id}/note")
    async def update_contact_note(
        user_id: int,
        payload: dict[str, Any],
        authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        note = payload.get("note")
        if not isinstance(note, str) or len(note.strip()) > 500:
            raise HTTPException(status_code=400, detail="Заметка должна содержать не более 500 символов")
        note = note.strip()
        owner_id = int(user["telegram_id"])
        now = int(time.time())
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            cur = await db.execute(
                "SELECT 1 FROM contacts WHERE owner_telegram_id=? AND contact_telegram_id=?",
                (owner_id, user_id),
            )
            if await cur.fetchone() is None:
                await db.rollback()
                raise HTTPException(status_code=404, detail="Сначала добавьте пользователя в контакты")
            if note:
                await db.execute(
                    """INSERT INTO contact_notes(owner_telegram_id,contact_telegram_id,note,updated_at)
                       VALUES(?,?,?,?)
                       ON CONFLICT(owner_telegram_id,contact_telegram_id) DO UPDATE SET
                           note=excluded.note,updated_at=excluded.updated_at""",
                    (owner_id, user_id, note, now),
                )
            else:
                await db.execute(
                    "DELETE FROM contact_notes WHERE owner_telegram_id=? AND contact_telegram_id=?",
                    (owner_id, user_id),
                )
            await db.commit()
        return {"user_id": user_id, "note": note, "updated_at": now if note else None}

