    @router.put("/api/channels/{channel_id}/reactions-settings")
    async def set_channel_reactions_settings(channel_id: int, payload: dict[str, Any],
                                             authorization: str | None = Header(default=None)):
        """Настройки реакций канала: включены ли, сколько и какие именно эмодзи."""
        uid = int((await current_user(authorization))["telegram_id"])
        if not await can_manage_channel(channel_id, uid):
            raise HTTPException(403, "CHANNEL_FORBIDDEN")
        fields: list[str] = []
        values: list[Any] = []
        if "enabled" in payload:
            enabled = payload["enabled"]
            if type(enabled) is not bool:
                raise HTTPException(400, "INVALID_REACTIONS_SETTING")
            fields.append("reactions_enabled=?")
            values.append(int(enabled))
        if "limit" in payload:
            limit = payload["limit"]
            if type(limit) is not int or not 1 <= limit <= 11:
                raise HTTPException(400, "INVALID_REACTIONS_LIMIT")
            fields.append("reactions_limit=?")
            values.append(limit)
        if "reactions" in payload:
            reactions = payload["reactions"]
            if (
                not isinstance(reactions, list)
                or len(reactions) > 100
                or any(not isinstance(item, str) or not item.strip() or len(item) > 32 for item in reactions)
            ):
                raise HTTPException(400, "INVALID_REACTIONS")
            fields.append("available_reactions=?")
            values.append(json.dumps(list(dict.fromkeys(item.strip() for item in reactions)), ensure_ascii=False))
        if not fields:
            raise HTTPException(400, "INVALID_REACTIONS_SETTING")
        values.append(channel_id)
        async with aiosqlite.connect(db_path()) as db:
            cur = await db.execute("UPDATE channels SET " + ",".join(fields) + " WHERE id=?", values)
            if not cur.rowcount:
                raise HTTPException(404, "CHANNEL_NOT_FOUND")
            await db.commit()
        async with aiosqlite.connect(db_path()) as db:
            cur = await db.execute(
                "SELECT reactions_enabled,reactions_limit,available_reactions FROM channels WHERE id=?",
                (channel_id,),
            )
            row = await cur.fetchone()
        if row is None:
            raise HTTPException(404, "CHANNEL_NOT_FOUND")
        try:
            reactions = json.loads(row[2] or "[]")
        except (TypeError, ValueError):
            reactions = []
        return {"enabled": bool(row[0]), "limit": int(row[1]), "reactions": reactions}

    @router.put("/api/channels/{channel_id}/paid-messages")
    async def set_channel_paid_messages(channel_id: int, payload: dict[str, Any],
                                        authorization: str | None = Header(default=None)) -> dict[str, Any]:
        """Цена «Direct Messages»: сколько звёзд платит подписчик за сообщение в канал."""
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        enabled = payload.get("enabled")
        stars = payload.get("stars", 0)
        if type(enabled) is not bool or type(stars) is not int or not 0 <= stars <= 10000:
            raise HTTPException(400, "INVALID_PAID_MESSAGES")
        if enabled and stars <= 0:
            raise HTTPException(400, "INVALID_PAID_MESSAGES")
        channel = await channel_row(channel_id)
        if int(channel["owner_telegram_id"]) != uid:
            raise HTTPException(403, "ONLY_OWNER_CAN_SET_PAID_MESSAGES")
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("UPDATE channels SET paid_messages_enabled=?,paid_messages_stars=? WHERE id=?",
                             (1 if enabled else 0, stars if enabled else 0, channel_id))
            await db.commit()
        updated = await channel_row(channel_id)
        return {
            "paid_messages_enabled": bool(updated.get("paid_messages_enabled") or 0),
            "send_paid_messages_stars": int(updated.get("paid_messages_stars") or 0),
        }

    @router.get("/api/channels/{channel_id}/messages/{message_id}/paid-reactions")
    async def get_channel_paid_reactions(channel_id: int, message_id: int, authorization: str | None = Header(default=None)):
        uid = int((await current_user(authorization))["telegram_id"])
        await require_channel_access(channel_id, uid)
        async with aiosqlite.connect(db_path()) as db:
            cur = await db.execute("""SELECT COALESCE(SUM(r.stars),0),
                COALESCE(SUM(CASE WHEN r.sender_id=? THEN r.stars ELSE 0 END),0)
                FROM channel_messages m LEFT JOIN channel_paid_reactions r
                ON r.channel_id=m.channel_id AND r.message_id=m.id
                WHERE m.channel_id=? AND m.id=? GROUP BY m.id""", (uid, channel_id, message_id))
            row = await cur.fetchone()
