    @router.get("/api/channels/{channel_id}/transfer")
    async def channel_transfer_options(channel_id: int, authorization: str | None = Header(default=None)):
        """Кому владелец может передать канал: только действующие администраторы.

        Нативный экран Telegram требует SRP-подтверждение, которого в WaysGram нет,
        поэтому клиент показывает свой список и при необходимости спрашивает пароль
        облачного пароля WaysGram.
        """
        uid = int((await current_user(authorization))["telegram_id"])
        channel = await channel_row(channel_id)
        if int(channel["owner_telegram_id"]) != uid:
            raise HTTPException(403, "CHANNEL_OWNER_REQUIRED")
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute(
                """SELECT ca.telegram_id,a.username,a.display_name,a.avatar_media_id
                   FROM channel_admins ca JOIN accounts a ON a.telegram_id=ca.telegram_id
                   WHERE ca.channel_id=? AND ca.telegram_id<>? AND a.is_banned=0
                   ORDER BY ca.created_at,ca.telegram_id""",
                (channel_id, uid),
            )
            rows = await avatar_visible_rows(db, await cur.fetchall(), uid)
            password_required = await cloud_password_row(db, uid) is not None
        return {"channel_id": channel_id, "password_required": password_required,
                "candidates": [dict(row) for row in rows]}

    @router.post("/api/channels/{channel_id}/transfer")
    async def transfer_channel(channel_id: int, payload: dict[str, Any],
                               authorization: str | None = Header(default=None)):
        """Передача владения каналом (channels.editCreator без SRP)."""
        uid = int((await current_user(authorization))["telegram_id"])
        new_owner = payload.get("new_owner_id")
        if type(new_owner) is not int or new_owner <= 0 or new_owner == uid:
            raise HTTPException(400, "NEW_OWNER_INVALID")
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            cur = await db.execute("SELECT owner_telegram_id FROM channels WHERE id=?", (channel_id,))
            owner = await cur.fetchone()
            if owner is None:
                raise HTTPException(404, "CHANNEL_NOT_FOUND")
            if int(owner[0]) != uid:
                raise HTTPException(403, "CHANNEL_OWNER_REQUIRED")
            cur = await db.execute("SELECT 1 FROM channel_admins WHERE channel_id=? AND telegram_id=?",
                                   (channel_id, new_owner))
            if not await cur.fetchone():
                raise HTTPException(400, "NEW_OWNER_MUST_BE_ADMIN")
            cur = await db.execute("SELECT 1 FROM accounts WHERE telegram_id=? AND is_banned=0", (new_owner,))
            if not await cur.fetchone():
                raise HTTPException(404, "ACCOUNT_NOT_FOUND")
            password = await cloud_password_row(db, uid)
            if password is not None:
                candidate = payload.get("password")
                if not valid_cloud_password(candidate):
                    raise HTTPException(401, "PASSWORD_MISSING")
                if not hmac.compare_digest(await cloud_verifier(candidate, password[0]), password[1]):
                    raise HTTPException(403, "PASSWORD_HASH_INVALID")
            await db.execute("UPDATE channels SET owner_telegram_id=? WHERE id=?", (new_owner, channel_id))
            await db.execute("DELETE FROM channel_admins WHERE channel_id=? AND telegram_id=?",
                             (channel_id, new_owner))
            await db.execute("""INSERT INTO channel_admins(channel_id,telegram_id,rights,created_at)
                VALUES(?,?,?,?) ON CONFLICT(channel_id,telegram_id) DO UPDATE SET rights=excluded.rights""",
                             (channel_id, uid, 127, int(time.time())))
            await log_channel_event(db, channel_id, uid, "transfer_owner",
                                    {"from": uid, "to": new_owner})
            await db.commit()
        return {"channel_id": channel_id, "owner_telegram_id": new_owner}

    async def attach_my_reactions(items: list[dict[str, Any]], scope: str, chat_id: int, user_id: int) -> None:
        message_ids = [int(item["id"]) for item in items if item.get("id") is not None]
        if not message_ids:
            return
        placeholders = ",".join("?" for _ in message_ids)
        async with aiosqlite.connect(db_path()) as db:
            cur = await db.execute(
                f"SELECT message_id,reaction FROM message_reactions WHERE scope=? AND chat_id=? AND user_telegram_id=? AND message_id IN ({placeholders}) ORDER BY created_at,reaction",
                (scope, chat_id, user_id, *message_ids),
            )
            rows = await cur.fetchall()
            cur = await db.execute(
                f"SELECT message_id,from_name,from_date FROM message_forward_sources WHERE scope=? AND message_id IN ({placeholders})",
                (scope, *message_ids),
            )
            card_rows = await db.execute(
                f"SELECT message_id,data_json FROM message_cards WHERE scope=? AND message_id IN ({placeholders})",
                (scope, *message_ids),
            )
            cards = {int(row[0]): json.loads(row[1]) for row in await card_rows.fetchall()}
            sources = {int(row[0]): (str(row[1]), int(row[2])) for row in await cur.fetchall()}
            if any(card["kind"] == "poll" for card in cards.values()):
                cur = await db.execute(
                    f"SELECT message_id,item_id,COUNT(*),MAX(voter=?) FROM message_card_votes WHERE scope=? AND message_id IN ({placeholders}) GROUP BY message_id,item_id",
                    (user_id, scope, *message_ids),
                )
                for mid, option, count, chosen in await cur.fetchall():
                    if mid in cards:
                        cards[mid].setdefault("votes", {})[str(option)] = {"count": count, "chosen": bool(chosen)}
                cur = await db.execute(
                    f"SELECT message_id,COUNT(DISTINCT voter) FROM message_card_votes WHERE scope=? AND message_id IN ({placeholders}) GROUP BY message_id",
                    (scope, *message_ids),
                )
                for mid, count in await cur.fetchall():
                    if mid in cards:
                        cards[mid]["voters"] = count
            locations = {}
            contacts = {}
            if scope in ("group", "channel"):
                cur = await db.execute(
                    f"SELECT message_id,latitude,longitude,label,venue_json FROM message_forward_locations WHERE scope=? AND message_id IN ({placeholders})",
                    (scope, *message_ids),
                )
                locations = {int(row[0]): tuple(row[1:]) for row in await cur.fetchall()}
                cur = await db.execute(
                    f"SELECT message_id,contact_name,contact_phone,contact_email,contact_first_name,contact_last_name,contact_vcard FROM message_scoped_contacts WHERE scope=? AND message_id IN ({placeholders})",
                    (scope, *message_ids),
                )
                contacts = {int(row[0]): tuple(row[1:]) for row in await cur.fetchall()}
            for item in items:
                author = item.get("forwarded_from_telegram_id")
                if author and not await privacy_allows(db, int(author), user_id, "forwards"):
                    item["forwarded_from_telegram_id"] = None
                    item["forwarded_from_message_id"] = None
        mine: dict[int, list[str]] = {}
        for message_id, reaction in rows:
            mine.setdefault(int(message_id), []).append(str(reaction))
        for item in items:
            _add_message_entities(item)
            if int(item["id"]) in cards:
                item["card"] = cards[int(item["id"])]
            item["my_reactions"] = mine.get(int(item["id"]), [])
            source = sources.get(int(item["id"]))
            if source:
                item["forwarded_from_display_name"] = source[0]
                item["forwarded_from_date"] = source[1]
            location = locations.get(int(item["id"]))
            if location:
                item.update(location_latitude=location[0], location_longitude=location[1], location_label=location[2], location_venue_json=location[3])
            contact = contacts.get(int(item["id"]))
            if contact:
                item.update(zip(("contact_name", "contact_phone", "contact_email", "contact_first_name", "contact_last_name", "contact_vcard"), contact))

    async def attach_paid_reactions(items: list[dict[str, Any]], channel_id: int, user_id: int) -> None:
        """Сумма звёзд платных реакций у каждого поста канала.

        Платная реакция живёт в отдельной таблице `channel_paid_reactions`, а не в
        `message_reactions`: там считается число реакций, а здесь важна сумма звёзд.
        Клиент рисует её отдельным чипом, поэтому в выдачу кладём `paid_stars` и
        `my_paid_stars` (0 — пользователь ещё не платил за этот пост).
        """
        message_ids = [int(item["id"]) for item in items if item.get("id") is not None]
        if not message_ids:
            return
        placeholders = ",".join("?" for _ in message_ids)
        async with aiosqlite.connect(db_path()) as db:
            cur = await db.execute(
                "SELECT message_id,COALESCE(SUM(stars),0),"
                "COALESCE(SUM(CASE WHEN sender_id=? THEN stars ELSE 0 END),0) "
                f"FROM channel_paid_reactions WHERE channel_id=? AND message_id IN ({placeholders}) "
                "GROUP BY message_id",
                (user_id, channel_id, *message_ids),
            )
            totals = {int(row[0]): (int(row[1]), int(row[2])) for row in await cur.fetchall()}
        for item in items:
            total, mine = totals.get(int(item["id"]), (0, 0))
            if total > 0:
                item["paid_stars"] = total
                item["my_paid_stars"] = mine

    def parse_history_ids(value: str | None, after_id: int, before_id: int, wait_seconds: int) -> list[int] | None:
        # Bounded point lookup uses exactly the same authorization and rendering
        # as history; it is not a second, less restrictive message endpoint.
        if value is None:
            return None
        if after_id or before_id or wait_seconds:
            raise HTTPException(status_code=400, detail="message_ids нельзя совмещать с курсорами или ожиданием")
        if len(value) > 2000 or not re.fullmatch(r"[1-9][0-9]*(?:,[1-9][0-9]*)*", value):
            raise HTTPException(status_code=400, detail="Некорректный список message_ids")
        values = value.split(",")
        if len(values) > 100 or any(len(v) > 19 for v in values):
            raise HTTPException(status_code=400, detail="Слишком много или слишком длинные message_ids")
        ids = [int(v) for v in values]
        if len(set(ids)) != len(ids) or any(v > 9223372036854775807 for v in ids):
            raise HTTPException(status_code=400, detail="Некорректный список message_ids")
        return ids

    @router.get("/api/channels/{channel_id}/messages")
    async def list_channel_messages(
        channel_id: int,
        after_id: int = Query(default=0, ge=0),
        before_id: int = Query(default=0, ge=0),
        limit: int = Query(default=100, ge=1, le=100),
        wait_seconds: int = Query(default=0, ge=0, le=20),
        message_ids: str | None = Query(default=None),
        authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        await require_channel_access(channel_id, int(user["telegram_id"]))
        if after_id and before_id:
            raise HTTPException(status_code=400, detail="Используйте только один курсор: after_id или before_id")
        selected_ids = parse_history_ids(message_ids, after_id, before_id, wait_seconds)
        deadline = time.monotonic() + (wait_seconds if after_id else 0)
        rows = []
        while True:
            await channel_row(channel_id)
            async with aiosqlite.connect(db_path()) as db:
                db.row_factory = aiosqlite.Row
                if selected_ids is not None:
                    # Re-check visibility in the same snapshot as the batch read.
                    await db.execute("BEGIN")
                    uid = int(user["telegram_id"])
                    cur = await db.execute(
                        """SELECT is_public,owner_telegram_id,
                                  EXISTS(SELECT 1 FROM channel_admins a WHERE a.channel_id=channels.id AND a.telegram_id=?) AS is_admin,
                                  EXISTS(SELECT 1 FROM active_channel_members m WHERE m.channel_id=channels.id AND m.telegram_id=?) AS is_member
                           FROM channels WHERE id=?""", (uid, uid, channel_id))
                    channel = await cur.fetchone()
                    if channel is None:
                        raise HTTPException(status_code=404, detail="Канал не найден")
                    if not (channel["is_public"] or channel["owner_telegram_id"] == uid
                            or channel["is_admin"] or channel["is_member"]):
                        raise HTTPException(status_code=403, detail="Это приватный канал. Нужна ссылка-приглашение.")
                if after_id:
                    cur = await db.execute(
                        """SELECT id,channel_id,author_telegram_id AS author_id,body,entities_json,channel_messages.silent AS silent,channel_messages.quote_json AS quote_json,media_id,media_album_id,media_album_index,media_album_count,edited_at,reply_to_id,created_at,
                                  (SELECT body FROM channel_messages AS replied WHERE replied.id=channel_messages.reply_to_id) AS reply_to_body,
                                  (SELECT author_telegram_id FROM channel_messages AS replied WHERE replied.id=channel_messages.reply_to_id) AS reply_to_sender_id,
                                  (SELECT group_concat(reaction || ':' || reaction_count, ',')
                                     FROM (SELECT reaction,COUNT(*) AS reaction_count FROM message_reactions
                                           WHERE scope='channel' AND chat_id=channel_messages.channel_id
                                             AND message_id=channel_messages.id GROUP BY reaction)) AS reaction_summary,
                                  (SELECT mime_type FROM media_assets WHERE id=channel_messages.media_id) AS media_type,
                                  (SELECT original_name FROM media_assets WHERE id=channel_messages.media_id) AS media_name,
                                  (SELECT media_kind FROM media_assets WHERE id=channel_messages.media_id) AS media_kind,
                                  (SELECT media_metadata FROM media_assets WHERE id=channel_messages.media_id) AS media_metadata, (SELECT COUNT(*) FROM channel_post_comments p WHERE p.channel_id=channel_messages.channel_id AND p.post_id=channel_messages.id) AS comments_count, (SELECT MAX(p.group_message_id) FROM channel_post_comments p WHERE p.channel_id=channel_messages.channel_id AND p.post_id=channel_messages.id) AS last_comment_id, (SELECT d.group_id FROM channel_discussion_groups d WHERE d.channel_id=channel_messages.channel_id) AS discussion_group_id
                           FROM channel_messages WHERE channel_id=? AND topic_id IS NULL AND id>?
                           ORDER BY id ASC LIMIT ?""",
                        (channel_id, after_id, limit),
                    )
                else:
                    id_filter = "" if selected_ids is None else " AND id IN (" + ",".join("?" for _ in selected_ids) + ")"
                    selected_limit = limit if selected_ids is None else len(selected_ids)
                    cur = await db.execute(
                        """SELECT id,channel_id,author_telegram_id AS author_id,body,entities_json,channel_messages.silent AS silent,channel_messages.quote_json AS quote_json,media_id,media_album_id,media_album_index,media_album_count,edited_at,reply_to_id,created_at,
                                  (SELECT body FROM channel_messages AS replied WHERE replied.id=channel_messages.reply_to_id) AS reply_to_body,
                                  (SELECT author_telegram_id FROM channel_messages AS replied WHERE replied.id=channel_messages.reply_to_id) AS reply_to_sender_id,
                                  (SELECT group_concat(reaction || ':' || reaction_count, ',')
                                     FROM (SELECT reaction,COUNT(*) AS reaction_count FROM message_reactions
                                           WHERE scope='channel' AND chat_id=channel_messages.channel_id
                                             AND message_id=channel_messages.id GROUP BY reaction)) AS reaction_summary,
                                  (SELECT mime_type FROM media_assets WHERE id=channel_messages.media_id) AS media_type,
                                  (SELECT original_name FROM media_assets WHERE id=channel_messages.media_id) AS media_name,
                                  (SELECT media_kind FROM media_assets WHERE id=channel_messages.media_id) AS media_kind,
                                  (SELECT media_metadata FROM media_assets WHERE id=channel_messages.media_id) AS media_metadata, (SELECT COUNT(*) FROM channel_post_comments p WHERE p.channel_id=channel_messages.channel_id AND p.post_id=channel_messages.id) AS comments_count, (SELECT MAX(p.group_message_id) FROM channel_post_comments p WHERE p.channel_id=channel_messages.channel_id AND p.post_id=channel_messages.id) AS last_comment_id, (SELECT d.group_id FROM channel_discussion_groups d WHERE d.channel_id=channel_messages.channel_id) AS discussion_group_id
                           FROM channel_messages WHERE channel_id=? AND topic_id IS NULL AND (?=0 OR id<?)""" + id_filter + " ORDER BY id DESC LIMIT ?",
                        (channel_id, before_id, before_id) + tuple(selected_ids or ()) + (selected_limit,),
                    )
                rows = await cur.fetchall()
            if rows or time.monotonic() >= deadline:
                break
            await asyncio.sleep(min(1.0, max(0.05, deadline - time.monotonic())))
        items = [dict(row) for row in rows]
        if not after_id:
            items.reverse()
        await attach_my_reactions(items, "channel", channel_id, int(user["telegram_id"]))
        await attach_paid_reactions(items, channel_id, int(user["telegram_id"]))
        return {"messages": items}

    def parse_reply_id(payload: dict[str, Any]) -> int | None:
        value = payload.get("reply_to_id")
        if value is None or value == 0:
            return None
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise HTTPException(status_code=400, detail="Некорректный reply_to_id")
        return value

    def parse_message_quote(payload: dict[str, Any], reply_to_id: int | None) -> dict[str, Any] | None:
        quote = payload.get("quote")
        if quote is None:
            return None
        if not reply_to_id or not isinstance(quote, dict) or set(quote) - {"text", "entities", "offset"}:
            raise HTTPException(status_code=400, detail="Некорректная цитата")
        text = quote.get("text")
        if not isinstance(text, str) or len(text) > 1024:
            raise HTTPException(status_code=400, detail="Некорректный текст цитаты")
        text, entities = _message_body_and_entities({"body": text, "entities": quote.get("entities", [])})
        offset = quote.get("offset")
        if offset is not None and (isinstance(offset, bool) or not isinstance(offset, int) or not 0 <= offset <= 100000):
            raise HTTPException(status_code=400, detail="Некорректное положение цитаты")
        result = {"text": text, "entities": entities}
        if offset is not None:
            result["offset"] = offset
        return result

    def album_allow_documents(payload: dict[str, Any], request: Request) -> bool:
        # A distinct route makes old servers reject the operation rather than
        # silently ignore a new field and misinterpret document albums.
        enabled = request.url.path.endswith(("/files", "/files/v2", "/files/quote/v1"))
        if "allow_documents" in payload:
            raise HTTPException(status_code=400, detail="Неизвестный параметр альбома")
        return enabled

    def album_media_class(fields: dict[str, str | None]) -> str:
        mime = str(fields.get("media_type") or "").lower()
        kind = str(fields.get("media_kind") or "").lower()
        name = str(fields.get("media_name") or "").lower()
        if kind in ("voice", "video_note", "gif") or (not kind and (
            (mime.startswith("video/") and name.startswith("round_video_")) or
            (mime.startswith("audio/") and name.startswith("audio_recording_voice_"))
        )):
            return "unsupported"
        if (mime.startswith("image/") and kind != "document") or (mime.startswith("video/") and kind == "video"):
            return "visual"
        return "document"

    def album_captions(payload: dict[str, Any], count: int, allow_documents: bool = False,
                       formatted: bool = False) -> tuple[list[str], str, list[list[dict[str, Any]]]]:
        if "entities" in payload or (not formatted and "caption_entities" in payload):
            raise HTTPException(status_code=400, detail="Используйте маршрут альбомов с форматированием")
        if formatted:
            captions = payload.get("captions")
            caption_entities = payload.get("caption_entities")
            if (not isinstance(captions, list) or len(captions) != count
                    or any(not isinstance(caption, str) for caption in captions)
                    or not isinstance(caption_entities, list) or len(caption_entities) != count):
                raise HTTPException(status_code=400, detail="Некорректные подписи альбома")
            checked = []
            validated_entities = []
            for caption, entities in zip(captions, caption_entities):
                if not caption.strip() and isinstance(entities, list) and not entities:
                    checked.append("")
                    validated_entities.append([])
                else:
                    text, validated = _message_body_and_entities({"body": caption, "entities": entities})
                    checked.append(text)
                    validated_entities.append(validated)
            if not any(checked):
                if count == 1 and allow_documents:
                    return checked, "Файл", validated_entities
                checked[0] = "Медиаальбом"
            return checked, next((caption for caption in checked if caption), "Медиаальбом"), validated_entities
        captions = payload.get("captions")
        if captions is None:
            text = str(payload.get("body") or "")
            if not text.strip() and count == 1 and allow_documents:
                return [""], "Файл", [[] for _ in range(count)]
            first = _message_body(text) if text.strip() else "Медиаальбом"
            return [first] + [""] * (count - 1), first, [[] for _ in range(count)]
        if not isinstance(captions, list) or len(captions) != count or any(not isinstance(v, str) for v in captions):
            raise HTTPException(status_code=400, detail="Некорректные подписи альбома")
        checked = [_message_body(v) if v.strip() else "" for v in captions]
        if not any(checked):
            if count == 1 and allow_documents:
                return checked, "Файл", [[] for _ in range(count)]
            checked[0] = "Медиаальбом"
        return checked, next((caption for caption in checked if caption), "Медиаальбом"), [[] for _ in range(count)]

    async def require_reply_target(db: Any, sql: str, params: tuple[Any, ...]) -> None:
        cur = await db.execute(sql, params)
        if await cur.fetchone() is None:
            await db.rollback()
            raise HTTPException(status_code=404, detail="Сообщение, на которое вы отвечаете, не найдено")

    @router.get("/api/channels/posts/search")
    async def search_public_channel_posts(
        q: str = "",
        limit: int = 30,
        offset_id: int = 0,
        authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        term = (q or "").strip()
        limit = max(1, min(50, limit))
        if not term:
            return {"query": "", "messages": [], "count": 0}
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            sql = """SELECT id,channel_id,author_telegram_id AS author_id,body,entities_json,
                            silent,quote_json,media_id,media_album_id,media_album_index,media_album_count,
                            edited_at,reply_to_id,created_at,
                            (SELECT mime_type FROM media_assets WHERE id=channel_messages.media_id) AS media_type,
                            (SELECT original_name FROM media_assets WHERE id=channel_messages.media_id) AS media_name,
                            (SELECT media_kind FROM media_assets WHERE id=channel_messages.media_id) AS media_kind,
                            (SELECT media_metadata FROM media_assets WHERE id=channel_messages.media_id) AS media_metadata, (SELECT COUNT(*) FROM channel_post_comments p WHERE p.channel_id=channel_messages.channel_id AND p.post_id=channel_messages.id) AS comments_count, (SELECT MAX(p.group_message_id) FROM channel_post_comments p WHERE p.channel_id=channel_messages.channel_id AND p.post_id=channel_messages.id) AS last_comment_id, (SELECT d.group_id FROM channel_discussion_groups d WHERE d.channel_id=channel_messages.channel_id) AS discussion_group_id
                     FROM channel_messages
                     WHERE body LIKE ? COLLATE NOCASE
                       AND channel_id IN (SELECT id FROM channels c WHERE c.is_public=1
                           AND NOT EXISTS(SELECT 1 FROM channel_bans b WHERE b.channel_id=c.id AND b.telegram_id=?
                               AND (b.until_date=0 OR b.until_date>CAST(strftime('%s','now') AS INTEGER))))"""
            params: list[Any] = [f"%{term}%", uid]
            if offset_id > 0:
                sql += " AND id<?"
                params.append(offset_id)
            sql += " ORDER BY id DESC LIMIT ?"
            params.append(limit)
            cur = await db.execute(sql, tuple(params))
            rows = [dict(row) for row in await cur.fetchall()]
        return {"query": term, "messages": rows, "count": len(rows)}

    @router.get("/api/channels/{channel_id}/messages/search")
    async def search_channel_messages(
        channel_id: int,
        q: str = Query(min_length=1, max_length=128),
        authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        await require_channel_access(channel_id, int(user["telegram_id"]))
        term = q.strip()
        if not term:
            raise HTTPException(status_code=400, detail="Введите текст для поиска")
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            await channel_row(channel_id)
            cur = await db.execute(
                """SELECT id,channel_id,author_telegram_id AS author_id,body,entities_json,channel_messages.silent AS silent,channel_messages.quote_json AS quote_json,media_id,media_album_id,media_album_index,media_album_count,edited_at,reply_to_id,created_at,
                          (SELECT body FROM channel_messages AS replied WHERE replied.id=channel_messages.reply_to_id) AS reply_to_body,
                                  (SELECT author_telegram_id FROM channel_messages AS replied WHERE replied.id=channel_messages.reply_to_id) AS reply_to_sender_id,
                                  (SELECT group_concat(reaction || ':' || reaction_count, ',')
                                     FROM (SELECT reaction,COUNT(*) AS reaction_count FROM message_reactions
                                           WHERE scope='channel' AND chat_id=channel_messages.channel_id
                                             AND message_id=channel_messages.id GROUP BY reaction)) AS reaction_summary,
                                  (SELECT mime_type FROM media_assets WHERE id=channel_messages.media_id) AS media_type,
                          (SELECT original_name FROM media_assets WHERE id=channel_messages.media_id) AS media_name,
                                  (SELECT media_kind FROM media_assets WHERE id=channel_messages.media_id) AS media_kind,
                                  (SELECT media_metadata FROM media_assets WHERE id=channel_messages.media_id) AS media_metadata, (SELECT COUNT(*) FROM channel_post_comments p WHERE p.channel_id=channel_messages.channel_id AND p.post_id=channel_messages.id) AS comments_count, (SELECT MAX(p.group_message_id) FROM channel_post_comments p WHERE p.channel_id=channel_messages.channel_id AND p.post_id=channel_messages.id) AS last_comment_id, (SELECT d.group_id FROM channel_discussion_groups d WHERE d.channel_id=channel_messages.channel_id) AS discussion_group_id
                   FROM channel_messages
                   WHERE channel_id=? AND body LIKE ? COLLATE NOCASE
                   ORDER BY id DESC LIMIT 100""",
                (channel_id, f"%{term}%"),
            )
            rows = await cur.fetchall()
        items = [dict(row) for row in rows]
        items.reverse()
        await attach_my_reactions(items, "channel", channel_id, int(user["telegram_id"]))
        await attach_paid_reactions(items, channel_id, int(user["telegram_id"]))
        return {"query": term, "messages": items, "count": len(items), "has_more": len(items) == 100}

    @router.post("/api/channels/{channel_id}/messages/quote/v1", status_code=201)
    @router.post("/api/channels/{channel_id}/messages", status_code=201)
    async def create_channel_message(
        channel_id: int,
        payload: dict[str, Any],
        authorization: str | None = Header(default=None),
        idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        silent = payload.get("silent", False)
        if not isinstance(silent, bool):
            raise HTTPException(status_code=400, detail="silent должен быть логическим значением")
        media_id = str(payload.get("media_id") or "").strip() or None
        contact_payload = _parse_message_contact(payload.get("contact"))
        location_payload = _parse_message_location(payload.get("location"))
        if contact_payload and (media_id or location_payload):
            raise HTTPException(status_code=400, detail="Нельзя объединять контакт с файлом или геолокацией")
        if location_payload and media_id:
            raise HTTPException(status_code=400, detail="Нельзя отправлять геолокацию вместе с файлом")
        card = _parse_message_card(payload.get("card"))
        if card and (contact_payload or location_payload or media_id or "entities" in payload):
            raise HTTPException(status_code=400, detail="Нельзя объединять опрос или чек-лист с другим вложением")
        body_value = str(payload.get("body") or "")
        if card:
            body_value = card["title"]
        elif contact_payload and not body_value.strip():
            body_value = "Контакт: " + contact_payload["name"]
        elif location_payload and not body_value.strip():
            body_value = str(location_payload["label"] or "Местоположение")
        if "entities" in payload:
            if contact_payload or location_payload:
                raise HTTPException(status_code=400, detail="Форматирование этого вложения пока не поддерживается")
            body, entities = _message_body_and_entities(payload)
        else:
            body = _message_body(body_value) if body_value.strip() or not media_id else ""
            entities = []
        if not await can_manage_channel(channel_id, uid):
            raise HTTPException(status_code=403, detail="Публиковать в канале может только владелец или администратор")
        now = int(time.time())
        scope = f"/api/channels/{channel_id}/messages"
        descriptor = idempotency_descriptor(scope, payload, idempotency_key)
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            # Verify posting rights under the same lock used for the message
            # and contact snapshot; demotion cannot race this write or replay.
            cur = await db.execute("""SELECT 1 FROM channels c WHERE c.id=? AND
                (c.owner_telegram_id=? OR EXISTS(SELECT 1 FROM channel_admins a
                WHERE a.channel_id=c.id AND a.telegram_id=? AND (a.rights & 1) != 0))""", (channel_id, uid, uid))
            if await cur.fetchone() is None:
                raise HTTPException(status_code=403, detail="Публиковать в канале может только владелец или администратор")
            previous = await idempotency_lookup(db, uid, scope, descriptor, now)
            if previous is not None:
                await db.rollback()
                return previous
            media_id = await require_owned_media(db, media_id, uid)
            if not body:
                body = _message_body(await default_media_message_body(db, media_id))
            media_fields = await media_message_fields(db, media_id)
            reply_to_id = parse_reply_id(payload)
            quote = parse_message_quote(payload, reply_to_id)
            if reply_to_id:
                await require_reply_target(
                    db, "SELECT 1 FROM channel_messages WHERE id=? AND channel_id=?", (reply_to_id, channel_id)
                )
            cur = await db.execute(
                "SELECT COUNT(*) FROM channel_messages WHERE author_telegram_id=? AND created_at>?",
                (uid, now - 60),
            )
            if int((await cur.fetchone())[0]) >= CHANNEL_POSTS_PER_MINUTE:
                await db.rollback()
                raise HTTPException(status_code=429, detail="Превышен лимит публикаций")
            cur = await db.execute(
                """INSERT INTO channel_messages
                   (channel_id,author_telegram_id,body,media_id,reply_to_id,created_at)
                   VALUES(?,?,?,?,?,?)""",
                (channel_id, uid, body, media_id, reply_to_id, now),
            )
            message_id = int(cur.lastrowid)
            if quote is not None:
                await db.execute("UPDATE channel_messages SET quote_json=? WHERE id=?",
                                 (json.dumps(quote, ensure_ascii=True, separators=(",", ":")), message_id))
            if silent:
                await db.execute("UPDATE channel_messages SET silent=1 WHERE id=?", (message_id,))
            if entities:
                await db.execute("UPDATE channel_messages SET entities_json=? WHERE id=?", (_message_entities_json(entities), message_id))
            if contact_payload:
                await db.execute(
                    """INSERT INTO message_scoped_contacts(scope,message_id,contact_name,contact_phone,contact_email,
                       contact_first_name,contact_last_name,contact_vcard) VALUES(?,?,?,?,?,?,?,?)""",
                    ("channel", message_id, contact_payload["name"], contact_payload["phone"],
                     contact_payload["email"], contact_payload.get("first_name", ""),
                     contact_payload.get("last_name", ""), contact_payload.get("vcard", "")),
                )
            if location_payload:
                await db.execute(
                    """INSERT INTO message_forward_locations(scope,message_id,latitude,longitude,label,venue_json)
                       VALUES(?,?,?,?,?,?)""",
                    ("channel", message_id, location_payload["latitude"],
                     location_payload["longitude"], location_payload["label"], _location_venue_json(location_payload)),
                )
            if card:
                await db.execute("INSERT INTO message_cards(scope,message_id,data_json) VALUES(?,?,?)",
                                 ("channel", message_id, json.dumps(card, ensure_ascii=True)))
            await record_event(
                db, "channel", message_id, "new_message", uid, chat_id=channel_id,
            )
            result = {"id": message_id, "status": "published", "channel_id": channel_id, "author_id": uid, "body": body, "media_id": media_id, "reply_to_id": reply_to_id, **media_fields, "created_at": now}
            if location_payload:
                result["location"] = location_payload
            if contact_payload:
                result["contact"] = contact_payload
            if quote is not None:
                result["quote"] = quote
            if entities:
                result["entities"] = entities
            if card:
                result["card"] = card
            await idempotency_store(db, uid, scope, descriptor, result, now)
            await db.commit()
        async with aiosqlite.connect(db_path()) as db:
            cur = await db.execute(
                "SELECT telegram_id FROM active_channel_members WHERE channel_id=? AND telegram_id<>?",
                (channel_id, uid),
            )
            channel_recipients = [int(row[0]) for row in await cur.fetchall()]
        await deliver_push_notifications(
            channel_recipients,
            str(user.get("display_name") or user.get("username") or "Новая публикация"),
            body,
            {"scope": "channel", "chat_id": str(channel_id), "message_id": str(message_id), "silent": "1" if silent else "0"},
        )
        return result

    @router.post("/api/channels/{channel_id}/messages/album/files/quote/v1", status_code=201)
    @router.post("/api/channels/{channel_id}/messages/album/files/v2", status_code=201)
    @router.post("/api/channels/{channel_id}/messages/album/files", status_code=201)
    @router.post("/api/channels/{channel_id}/messages/album", status_code=201)
    async def create_channel_message_album(
        channel_id: int,
        payload: dict[str, Any],
        request: Request,
        authorization: str | None = Header(default=None),
        idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        allow_documents = album_allow_documents(payload, request)
        raw_media_ids = payload.get("media_ids")
        minimum = 1 if allow_documents else 2
        if not isinstance(raw_media_ids, list) or not minimum <= len(raw_media_ids) <= 10:
            raise HTTPException(status_code=400, detail="Выберите не более 10 файлов")
        media_ids: list[str] = []
        for raw_id in raw_media_ids:
            media_id = str(raw_id or "").strip()
            if not re.fullmatch(r"[a-f0-9]{32}", media_id):
                raise HTTPException(status_code=400, detail="Некорректный ID вложения в альбоме")
            media_ids.append(media_id)
        if not allow_documents and len(set(media_ids)) != len(media_ids):
            raise HTTPException(status_code=400, detail="Альбом не должен содержать повторяющиеся файлы")

        captions, body, caption_entities = album_captions(
            payload, len(media_ids), allow_documents, request.url.path.endswith(("/files/v2", "/files/quote/v1"))
        )
        silent = payload.get("silent", False)
        if not isinstance(silent, bool):
            raise HTTPException(status_code=400, detail="silent должен быть логическим значением")

        now = int(time.time())
        scope = f"/api/channels/{channel_id}/messages/album"
        if allow_documents:
            scope += "/files"
        descriptor = idempotency_descriptor(scope, payload, idempotency_key)
        album_id = secrets.token_hex(16)
        created_messages: list[dict[str, Any]] = []

        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            await db.execute("BEGIN IMMEDIATE")
            # Check publishing rights in the same transaction as insertion.
            cur = await db.execute(
                """SELECT 1 FROM channels c WHERE c.id=? AND
                   (c.owner_telegram_id=? OR EXISTS(
                       SELECT 1 FROM channel_admins a WHERE a.channel_id=c.id AND a.telegram_id=? AND (a.rights & 1) != 0))""",
                (channel_id, uid, uid),
            )
            if await cur.fetchone() is None:
                raise HTTPException(status_code=403, detail="Публиковать в канале может только владелец или администратор")
            previous = await idempotency_lookup(db, uid, scope, descriptor, now)
            if previous is not None:
                await db.rollback()
                return previous

            checked_media: list[tuple[str, dict[str, str | None]]] = []
            batch_classes: set[str] = set()
            for media_id in media_ids:
                owned_id = await require_owned_media(db, media_id, uid)
                fields = await media_message_fields(db, owned_id)
                media_type = str(fields.get("media_type") or "").lower()
                if not allow_documents:
                    if not (media_type.startswith("image/") or media_type.startswith("video/")):
                        raise HTTPException(status_code=415, detail="В медиаальбом можно добавлять только фотографии и видео")
                else:
                    media_class = album_media_class(fields)
                    if media_class == "unsupported":
                        raise HTTPException(status_code=415, detail="Голосовые и видеосообщения нельзя включать в набор файлов")
                    batch_classes.add(media_class)
                checked_media.append((media_id, fields))
            # Native clients render document and visual groups differently. Never
            # create a group that would be rendered as the wrong kind of media.
            if len(batch_classes) > 1:
                raise HTTPException(status_code=415, detail="Файлы и фотографии/видео нужно отправить отдельными группами")

            reply_to_id = parse_reply_id(payload)
            quote = parse_message_quote(payload, reply_to_id)
            if reply_to_id:
                await require_reply_target(
                    db,
                    "SELECT 1 FROM channel_messages WHERE id=? AND channel_id=?",
                    (reply_to_id, channel_id),
                )

            cur = await db.execute(
                "SELECT COUNT(*) FROM channel_messages WHERE author_telegram_id=? AND created_at>?",
                (uid, now - 60),
            )
            sent_recently = int((await cur.fetchone())[0])
            if sent_recently + len(checked_media) > CHANNEL_POSTS_PER_MINUTE:
                await db.rollback()
                raise HTTPException(status_code=429, detail="Превышен лимит публикаций для медиаальбома")

            for index, (media_id, media_fields) in enumerate(checked_media):
                item_body = captions[index]
                cur = await db.execute(
                    """INSERT INTO channel_messages
                       (channel_id,author_telegram_id,body,media_id,reply_to_id,
                        media_album_id,media_album_index,media_album_count,created_at)
                       VALUES(?,?,?,?,?,?,?,?,?)""",
                    (
                        channel_id, uid, item_body, media_id, reply_to_id,
                        album_id, index, len(checked_media), now,
                    ),
                )
                message_id = int(cur.lastrowid)
                if quote is not None:
                    await db.execute("UPDATE channel_messages SET quote_json=? WHERE id=?",
                                     (json.dumps(quote, ensure_ascii=True, separators=(",", ":")), message_id))
                if silent:
                    await db.execute("UPDATE channel_messages SET silent=1 WHERE id=?", (message_id,))
                if caption_entities[index]:
                    await db.execute("UPDATE channel_messages SET entities_json=? WHERE id=?",
                                     (_message_entities_json(caption_entities[index]), message_id))
                await record_event(db, "channel", message_id, "new_message", uid, chat_id=channel_id)
                created_messages.append({
                    "id": message_id,
                    "channel_id": channel_id,
                    "author_id": uid,
                    "body": item_body,
                    "media_id": media_id,
                    "reply_to_id": reply_to_id,
                    "quote": quote,
                    "media_album_id": album_id,
                    "media_album_index": index,
                    "media_album_count": len(checked_media),
                    **media_fields,
                    "created_at": now,
                })
                if caption_entities[index]:
                    created_messages[-1]["entities"] = caption_entities[index]

            result = {
                "status": "published",
                "album_id": album_id,
                "channel_id": channel_id,
                "count": len(created_messages),
                "first_message_id": created_messages[0]["id"],
                "last_message_id": created_messages[-1]["id"],
                "messages": created_messages,
            }
            await idempotency_store(db, uid, scope, descriptor, result, now)
            await db.commit()

        async with aiosqlite.connect(db_path()) as db:
            cur = await db.execute(
                "SELECT telegram_id FROM active_channel_members WHERE channel_id=? AND telegram_id<>?",
                (channel_id, uid),
            )
            recipients = [int(row[0]) for row in await cur.fetchall()]
        await deliver_push_notifications(
            recipients,
            str(user.get("display_name") or user.get("username") or "Новая публикация"),
            f"{'Файлы' if batch_classes == {'document'} else 'Медиаальбом'} · {len(created_messages)} вложений",
            {
                "scope": "channel",
                "chat_id": str(channel_id),
                "message_id": str(created_messages[-1]["id"]),
                "media_album_id": album_id,
                "silent": "1" if silent else "0",
            },
        )
        return result

    @router.post("/api/channels/{channel_id}/admins", status_code=201)
    async def add_channel_admin(
        channel_id: int,
        payload: dict[str, Any],
        authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        if int((await channel_row(channel_id))["owner_telegram_id"]) != uid:
            raise HTTPException(status_code=403, detail="Только владелец может назначать администраторов")
        try:
            target_id = int(payload.get("telegram_id", 0))
        except (TypeError, ValueError):
            target_id = 0
        if target_id <= 0:
            raise HTTPException(status_code=400, detail="Некорректный Telegram ID")
        rights = payload.get("rights", 15)
        if type(rights) is not int or not 1 <= rights <= 127:
            raise HTTPException(400, "Некорректные права администратора")
        if target_id == uid:
            raise HTTPException(409, "Нельзя изменить права владельца")
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            await require_channel_not_banned(db, channel_id, target_id)
            cur = await db.execute("SELECT 1 FROM accounts WHERE telegram_id=?", (target_id,))
            if not await cur.fetchone():
                raise HTTPException(status_code=404, detail="Пользователь не найден")
            joined_at = int(time.time())
            await db.execute(
                """INSERT INTO channel_admins(channel_id,telegram_id,created_at,rights) VALUES(?,?,?,?)
                   ON CONFLICT(channel_id,telegram_id) DO UPDATE SET rights=excluded.rights""",
                (channel_id, target_id, joined_at, rights),
            )
            await db.execute(
                "INSERT OR IGNORE INTO channel_members(channel_id,telegram_id,joined_at) VALUES(?,?,?)",
                (channel_id, target_id, joined_at),
            )
            await db.execute("DELETE FROM channel_join_requests WHERE channel_id=? AND telegram_id=?", (channel_id, target_id))
            await log_channel_event(db, channel_id, uid, "participant_promote",
                                    {"telegram_id": target_id, "rights": rights})
            await record_event(db, "channel", 0, "chat_changed", uid, chat_id=channel_id)
            await db.commit()
        return {"channel_id": channel_id, "telegram_id": target_id, "admin": True}

    @router.delete("/api/channels/{channel_id}/admins/{telegram_id}")
    async def remove_channel_admin(
        channel_id: int,
        telegram_id: int,
        authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        channel = await channel_row(channel_id)
        if int(channel["owner_telegram_id"]) != int(user["telegram_id"]):
            raise HTTPException(status_code=403, detail="Только владелец может удалять администраторов")
        async with aiosqlite.connect(db_path()) as db:
            cur = await db.execute(
                "DELETE FROM channel_admins WHERE channel_id=? AND telegram_id=?",
                (channel_id, telegram_id),
            )
            if cur.rowcount:
                await log_channel_event(db, channel_id, int(user["telegram_id"]), "participant_demote",
                                        {"telegram_id": telegram_id})
                await record_event(db, "channel", 0, "chat_changed", int(user["telegram_id"]), chat_id=channel_id)
            await db.commit()
        if cur.rowcount == 0:
            raise HTTPException(status_code=404, detail="Администратор канала не найден")
        return {"deleted": True, "channel_id": channel_id, "telegram_id": telegram_id}

