    async def credit_chat_stars(db: Any, chat_id: int, amount: int, reason: str, now: int) -> int:
        """Звёзды, которые уходят каналу или группе, лежат на их собственном балансе.

        Это внутренний счёт чата (в будущем — счёт fragment): звёзды списываются у
        отправителя, но владельцу в личный кошелёк не начисляются и нигде в
        интерфейсе не показываются.
        """
        if amount <= 0:
            return 0
        await db.execute("""INSERT INTO chat_stars(chat_id,stars) VALUES(?,?)
            ON CONFLICT(chat_id) DO UPDATE SET stars=stars+excluded.stars""", (chat_id, amount))
        cur = await db.execute("SELECT stars FROM chat_stars WHERE chat_id=?", (chat_id,))
        balance = int((await cur.fetchone())[0])
        await cur.close()
        await db.execute("""INSERT INTO chat_star_transactions(chat_id,amount,balance_after,reason,created_at)
            VALUES(?,?,?,?,?)""", (chat_id, amount, balance, reason, now))
        return balance

    async def debit_chat_stars(db: Any, chat_id: int, amount: int, reason: str, now: int) -> int:
        """Обратная операция для возвратов: списывает не больше, чем есть на балансе чата."""
        if amount <= 0:
            return 0
        cur = await db.execute("SELECT stars FROM chat_stars WHERE chat_id=?", (chat_id,))
        row = await cur.fetchone()
        await cur.close()
        amount = min(amount, int(row[0]) if row else 0)
        if amount <= 0:
            return 0
        cur = await db.execute("UPDATE chat_stars SET stars=stars-? WHERE chat_id=? RETURNING stars",
                               (amount, chat_id))
        balance = int((await cur.fetchone())[0])
        await cur.close()
        await db.execute("""INSERT INTO chat_star_transactions(chat_id,amount,balance_after,reason,created_at)
            VALUES(?,?,?,?,?)""", (chat_id, -amount, balance, reason, now))
        return amount

    async def charge_dm_fee(db: Any, sender: int, recipient: int, stars: int, message_id: int, now: int) -> None:
        for uid, amount in ((sender, -stars), (recipient, stars)):
            cur = await db.execute("UPDATE accounts SET stars=stars+? WHERE telegram_id=? AND stars+? BETWEEN 0 AND 9223372036854775807 RETURNING stars",
                                   (amount, uid, amount))
            row = await cur.fetchone()
            await cur.close()
            if row is None:
                raise HTTPException(409, "MESSAGE_FEE_INSUFFICIENT_STARS")
            await db.execute("""INSERT INTO economy_transactions
                (telegram_id,asset,amount,balance_after,reason,admin_id,created_at) VALUES(?,'stars',?,?,?,NULL,?)""",
                (uid, amount, row[0], f"message_fee:{message_id}", now))

    PAID_MESSAGE_REASONS_SQL = ("reason LIKE 'message_fee:%' OR reason LIKE 'channel_inbox:%' "
                                "OR reason LIKE 'channel_inbox_refund:%' OR reason LIKE 'channel_sponsored_post:%'")

    @router.get("/api/me/paid-messages")
    async def paid_messages_history(before_id: int = Query(default=0, ge=0),
                                    limit: int = Query(default=40, ge=1, le=100),
                                    authorization: str | None = Header(default=None)):
        """История платных сообщений так, как её показывает Telegram.

        Одна лента на все платные отправки: личные сообщения, сообщения в канал и
        возвраты за недоставленные. Суммы берутся из журнала, поэтому повторный
        запрос с тем же Idempotency-Key не добавляет вторую строку.
        """
        uid = int((await current_user(authorization))["telegram_id"])
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            # Возвраты считаются до выборки, чтобы история всегда сходилась с балансом.
            await refund_undelivered_inbox(db, int(time.time()))
            await db.commit()
            db.row_factory = aiosqlite.Row
            cur = await db.execute(f"""SELECT id,amount,balance_after,reason,created_at FROM economy_transactions
                WHERE telegram_id=? AND (?=0 OR id<?) AND ({PAID_MESSAGE_REASONS_SQL})
                ORDER BY id DESC LIMIT ?""", (uid, before_id, before_id, limit + 1))
            rows = await cur.fetchall()
            cur = await db.execute(f"""SELECT COALESCE(SUM(CASE WHEN amount<0 THEN -amount ELSE 0 END),0),
                COALESCE(SUM(CASE WHEN amount>0 AND reason LIKE 'channel_inbox_refund:%' THEN amount ELSE 0 END),0),
                COALESCE(SUM(CASE WHEN amount>0 AND reason NOT LIKE 'channel_inbox_refund:%' THEN amount ELSE 0 END),0),
                COUNT(*) FROM economy_transactions WHERE telegram_id=? AND ({PAID_MESSAGE_REASONS_SQL})""", (uid,))
            spent, refunded, earned, total = await cur.fetchone()
            titles: dict[str, str] = {}
            items = []
            for row in rows[:limit]:
                reason = row["reason"]
                parts = reason.split(":")
                kind = parts[0]
                title = ""
                if kind == "message_fee":
                    if reason not in titles:
                        cur = await db.execute("""SELECT a.display_name FROM messages m
                            LEFT JOIN accounts a ON a.telegram_id=m.recipient_telegram_id WHERE m.id=?""",
                            (int(parts[1]) if len(parts) > 1 and parts[1].isdigit() else 0,))
                        name = await cur.fetchone()
                        titles[reason] = (name[0] if name and name[0] else "")
                    title = titles[reason]
                elif len(parts) > 1 and parts[1].isdigit():
                    if parts[1] not in titles:
                        cur = await db.execute("SELECT title FROM channels WHERE id=?", (int(parts[1]),))
                        channel = await cur.fetchone()
                        titles[parts[1]] = (channel[0] if channel and channel[0] else "")
                    title = titles[parts[1]]
                items.append({
                    "id": row["id"],
                    "kind": {"message_fee": "direct", "channel_inbox": "channel",
                             "channel_inbox_refund": "refund", "channel_sponsored_post": "sponsored"}.get(kind, kind),
                    "title": title,
                    "stars": -row["amount"] if row["amount"] < 0 else row["amount"],
                    "refunded": kind == "channel_inbox_refund",
                    "balance_after": row["balance_after"],
                    "created_at": row["created_at"],
                })
        return {"transactions": items, "next_before_id": rows[limit - 1]["id"] if len(rows) > limit else 0,
                "spent_stars": int(spent), "refunded_stars": int(refunded), "earned_stars": int(earned),
                "total": int(total), "refund_after_seconds": CHANNEL_INBOX_REFUND_AFTER}

    @router.post("/api/messages/quote/v1", status_code=201)
    @router.post("/api/messages", status_code=201)
    async def send_message(
        payload: dict[str, Any],
        authorization: str | None = Header(default=None),
        idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        try:
            recipient_id = int(payload.get("recipient_id", payload.get("to", 0)))
        except (TypeError, ValueError):
            recipient_id = 0
        if recipient_id <= 0:
            raise HTTPException(status_code=400, detail="Укажите корректного получателя")
        media_id = str(payload.get("media_id") or "").strip() or None
        contact_value = payload.get("contact")
        contact_payload: dict[str, str] | None = None
        location_payload = _parse_message_location(payload.get("location"))
        contact_payload = _parse_message_contact(contact_value)
        if contact_payload and (media_id or location_payload):
            raise HTTPException(status_code=400, detail="Нельзя объединять контакт с файлом или геолокацией")
        if location_payload and media_id:
            raise HTTPException(status_code=400, detail="Нельзя отправлять геолокацию вместе с файлом")
        card = _parse_message_card(payload.get("card"))
        if card and (contact_payload or location_payload or media_id or "entities" in payload):
            raise HTTPException(status_code=400, detail="Нельзя объединять опрос или чек-лист с другим вложением")
        body_value = str(payload.get("body") or "")
        if card:
            body_value = card["title"]
        elif contact_payload and not body_value.strip():
            body_value = "Контакт: " + contact_payload["name"]
        elif location_payload and not body_value.strip():
            body_value = location_payload["label"] or "Местоположение"
        if "entities" in payload:
            if contact_payload or location_payload:
                raise HTTPException(status_code=400, detail="Форматирование этого вложения пока не поддерживается")
            body, entities = _message_body_and_entities(payload)
        else:
            body = _message_body(body_value) if body_value.strip() or not media_id else ""
            entities = []
        silent = payload.get("silent", False)
        if not isinstance(silent, bool):
            raise HTTPException(status_code=400, detail="silent должен быть логическим значением")
        now = int(time.time())
        descriptor = idempotency_descriptor("/api/messages", payload, idempotency_key)
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            previous = await idempotency_lookup(db, uid, "/api/messages", descriptor, now)
            if previous is not None:
                await db.rollback()
                return previous
            media_id = await require_owned_media(db, media_id, uid)
            if not body:
                body = _message_body(await default_media_message_body(db, media_id))
            media_fields = await media_message_fields(db, media_id)
            await require_voice_privacy(db, recipient_id, uid, media_fields)
            cur = await db.execute(
                "SELECT is_banned FROM accounts WHERE telegram_id=?",
                (recipient_id,),
            )
            recipient = await cur.fetchone()
            if not recipient:
                await db.rollback()
                raise HTTPException(status_code=404, detail="Получатель не найден")
            if recipient[0]:
                await db.rollback()
                raise HTTPException(status_code=403, detail="Получатель заблокирован")
            if recipient_id != uid:
                cur = await db.execute(
                    """SELECT 1 FROM blocked_users
                       WHERE (owner_telegram_id=? AND blocked_telegram_id=?)
                          OR (owner_telegram_id=? AND blocked_telegram_id=?)
                       LIMIT 1""",
                    (uid, recipient_id, recipient_id, uid),
                )
                if await cur.fetchone():
                    await db.rollback()
                    raise HTTPException(status_code=403, detail="Нельзя отправить сообщение: пользователь находится в чёрном списке")
            reply_to_id = parse_reply_id(payload)
            quote = parse_message_quote(payload, reply_to_id)
            if reply_to_id:
                await require_reply_target(
                    db,
                    """SELECT 1 FROM messages WHERE id=? AND
                       ((sender_telegram_id=? AND recipient_telegram_id=?) OR (sender_telegram_id=? AND recipient_telegram_id=?))""",
                    (reply_to_id, uid, recipient_id, recipient_id, uid),
                )
            cur = await db.execute(
                "SELECT COUNT(*) FROM messages WHERE sender_telegram_id=? AND created_at>?",
                (uid, now - 60),
            )
            if int((await cur.fetchone())[0]) >= DM_MESSAGES_PER_MINUTE:
                await db.rollback()
                raise HTTPException(status_code=429, detail="Превышен лимит отправки сообщений")
            fee = await dm_message_fee(db, uid, recipient_id)
            if fee or "approved_fee_stars" in payload:
                allowed = payload.get("approved_fee_stars")
                if type(allowed) is not int or allowed != fee:
                    raise HTTPException(402, {"code": "MESSAGE_FEE_REQUIRED", "stars": fee})
                if descriptor is None:
                    raise HTTPException(400, "MESSAGE_FEE_IDEMPOTENCY_REQUIRED")
            cur = await db.execute(
                """INSERT INTO messages
                   (sender_telegram_id,recipient_telegram_id,body,media_id,reply_to_id,created_at)
                   VALUES(?,?,?,?,?,?)""",
                (uid, recipient_id, body, media_id, reply_to_id, now),
            )
            message_id = int(cur.lastrowid)
            if fee:
                await charge_dm_fee(db, uid, recipient_id, fee, message_id, now)
            if quote is not None:
                await db.execute("UPDATE messages SET quote_json=? WHERE id=?",
                                 (json.dumps(quote, ensure_ascii=True, separators=(",", ":")), message_id))
            if silent:
                await db.execute("UPDATE messages SET silent=1 WHERE id=?", (message_id,))
            if entities:
                await db.execute("UPDATE messages SET entities_json=? WHERE id=?", (_message_entities_json(entities), message_id))
            if contact_payload:
                await db.execute(
                    """INSERT INTO message_contacts
                       (message_id,contact_name,contact_phone,contact_email,
                        contact_first_name,contact_last_name,contact_vcard)
                       VALUES(?,?,?,?,?,?,?)""",
                    (
                        message_id,
                        contact_payload["name"],
                        contact_payload["phone"],
                        contact_payload["email"],
                        contact_payload.get("first_name", ""),
                        contact_payload.get("last_name", ""),
                        contact_payload.get("vcard", ""),
                    ),
                )
            if location_payload:
                await db.execute(
                    """INSERT INTO message_locations
                       (message_id,latitude,longitude,label,venue_json)
                       VALUES(?,?,?,?,?)""",
                    (
                        message_id,
                        location_payload["latitude"],
                        location_payload["longitude"],
                        location_payload["label"],
                        _location_venue_json(location_payload),
                    ),
                )
            if card:
                await db.execute("INSERT INTO message_cards(scope,message_id,data_json) VALUES(?,?,?)",
                                 ("dm", message_id, json.dumps(card, ensure_ascii=True)))
            await record_event(
                db, "dm", message_id, "new_message", uid,
                user_a=uid, user_b=recipient_id,
            )
            result = {
                "id": message_id,
                "status": "sent",
                "sender_id": uid,
                "recipient_id": recipient_id,
                "body": body,
                "media_id": media_id,
                "reply_to_id": reply_to_id,
                "contact": contact_payload,
                "location": location_payload,
                **media_fields,
                "created_at": now,
            }
            if quote is not None:
                result["quote"] = quote
            if entities:
                result["entities"] = entities
            if card:
                result["card"] = card
            await idempotency_store(db, uid, "/api/messages", descriptor, result, now)
            queued_push = False
            if recipient_id != uid and not silent:
                queued_push = await enqueue_push(
                    db, uid, recipient_id, str(user.get("display_name") or user.get("username") or "Новое сообщение"),
                    body, {"scope": "dm", "chat_id": str(uid), "message_id": str(message_id), "silent": "1" if silent else "0"}, now,
                )
            await db.commit()
        for waiter in dm_event_waiters.get(recipient_id, ()):
            waiter.set()
        if queued_push:
            push_wakeup.set()
        return result


    @router.post("/api/messages/live-location", status_code=201)
    async def upsert_live_location(
        payload: dict[str, Any],
        authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        raw_recipient = payload.get("recipient_id")
        if (isinstance(raw_recipient, bool)
                or not (isinstance(raw_recipient, int) or isinstance(raw_recipient, str) and raw_recipient.isascii() and raw_recipient.isdecimal())):
            raise HTTPException(status_code=400, detail="Укажите корректного получателя геолокации")
        try:
            recipient_id = int(raw_recipient)
        except (TypeError, ValueError, OverflowError):
            recipient_id = 0
        if recipient_id <= 0 or recipient_id > 9223372036854775807 or recipient_id == uid:
            raise HTTPException(status_code=400, detail="Укажите корректного получателя геолокации")

        raw_latitude = payload.get("latitude")
        raw_longitude = payload.get("longitude")
        raw_accuracy = payload.get("accuracy_m")
        if isinstance(raw_latitude, bool) or isinstance(raw_longitude, bool) or isinstance(raw_accuracy, bool):
            raise HTTPException(status_code=400, detail="Координаты должны быть числовыми значениями")
        try:
            latitude = float(raw_latitude)
            longitude = float(raw_longitude)
            accuracy = None if raw_accuracy is None else float(raw_accuracy)
        except (TypeError, ValueError, OverflowError):
            raise HTTPException(status_code=400, detail="Укажите корректные координаты")
        if not math.isfinite(latitude) or not math.isfinite(longitude):
            raise HTTPException(status_code=400, detail="Координаты должны быть конечными числами")
        if not (-90.0 <= latitude <= 90.0) or not (-180.0 <= longitude <= 180.0):
            raise HTTPException(status_code=400, detail="Координаты выходят за допустимый диапазон")
        if accuracy is not None and (
            not math.isfinite(accuracy) or accuracy < 0 or accuracy > 10000
        ):
            raise HTTPException(status_code=400, detail="Некорректная точность геолокации")

        live_id = str(payload.get("live_location_id") or "").strip()
        now = int(time.time())
        created = False
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            await db.execute("BEGIN IMMEDIATE")
            cur = await db.execute(
                "SELECT is_banned FROM accounts WHERE telegram_id=?",
                (recipient_id,),
            )
            recipient = await cur.fetchone()
            if recipient is None:
                await db.rollback()
                raise HTTPException(status_code=404, detail="Получатель не найден")
            if recipient["is_banned"]:
                await db.rollback()
                raise HTTPException(status_code=403, detail="Получатель заблокирован")
            cur = await db.execute(
                """SELECT 1 FROM blocked_users
                   WHERE (owner_telegram_id=? AND blocked_telegram_id=?)
                      OR (owner_telegram_id=? AND blocked_telegram_id=?)
                   LIMIT 1""",
                (uid, recipient_id, recipient_id, uid),
            )
            if await cur.fetchone():
                await db.rollback()
                raise HTTPException(status_code=403, detail="Нельзя делиться геолокацией: пользователь находится в чёрном списке")

            if not live_id:
                await require_free_dm(db, uid, recipient_id)
            if live_id:
                if not re.fullmatch(r"[a-f0-9]{32}", live_id):
                    await db.rollback()
                    raise HTTPException(status_code=400, detail="Некорректный ID трансляции геолокации")
                cur = await db.execute(
                    """UPDATE live_locations
                       SET latitude=?,longitude=?,accuracy_m=?,updated_at=?
                       WHERE id=? AND sender_telegram_id=? AND recipient_telegram_id=?
                         AND stopped_at IS NULL AND expires_at>?""",
                    (latitude, longitude, accuracy, now, live_id, uid, recipient_id, now),
                )
                if cur.rowcount != 1:
                    await db.rollback()
                    raise HTTPException(status_code=404, detail="Трансляция геолокации завершена или не найдена")
                cur = await db.execute(
                    """SELECT id,sender_telegram_id,recipient_telegram_id,latitude,longitude,
                              accuracy_m,started_at,updated_at,expires_at
                       FROM live_locations WHERE id=?""",
                    (live_id,),
                )
                row = await cur.fetchone()
            else:
                raw_duration = payload.get("duration_seconds", 0)
                if isinstance(raw_duration, bool) or not (
                    isinstance(raw_duration, int) or isinstance(raw_duration, str) and raw_duration in ("900", "3600", "28800")
                ):
                    raise HTTPException(status_code=400, detail="Длительность трансляции должна быть 15 минут, 1 час или 8 часов")
                duration = int(raw_duration)
                if duration not in (900, 3600, 28800):
                    await db.rollback()
                    raise HTTPException(status_code=400, detail="Длительность трансляции должна быть 15 минут, 1 час или 8 часов")
                cur = await db.execute(
                    """UPDATE live_locations SET stopped_at=?,stopped_by_telegram_id=?,latitude=0,longitude=0,accuracy_m=NULL
                       WHERE sender_telegram_id=? AND recipient_telegram_id=?
                         AND stopped_at IS NULL AND expires_at<=?""",
                    (now, uid, uid, recipient_id, now),
                )
                cur = await db.execute(
                    """SELECT id FROM live_locations
                       WHERE sender_telegram_id=? AND recipient_telegram_id=?
                         AND stopped_at IS NULL AND expires_at>? LIMIT 1""",
                    (uid, recipient_id, now),
                )
                if await cur.fetchone():
                    await db.rollback()
                    raise HTTPException(status_code=409, detail="Для этого собеседника уже идёт трансляция геолокации")
                live_id = secrets.token_hex(16)
                await db.execute(
                    """INSERT INTO live_locations(
                           id,sender_telegram_id,recipient_telegram_id,latitude,longitude,
                           accuracy_m,started_at,updated_at,expires_at
                       ) VALUES(?,?,?,?,?,?,?,?,?)""",
                    (
                        live_id, uid, recipient_id, latitude, longitude,
                        accuracy, now, now, now + duration,
                    ),
                )
                cur = await db.execute(
                    """SELECT id,sender_telegram_id,recipient_telegram_id,latitude,longitude,
                              accuracy_m,started_at,updated_at,expires_at
                       FROM live_locations WHERE id=?""",
                    (live_id,),
                )
                row = await cur.fetchone()
                created = True
            await db.commit()

        result = dict(row)
        result["status"] = "active"
        result["created"] = created
        if created:
            await deliver_push_notifications(
                [recipient_id],
                str(user.get("display_name") or user.get("username") or "WaysGram"),
                "Пользователь начал делиться геолокацией в реальном времени",
                {"scope": "dm", "chat_id": str(uid), "event": "live_location_started"},
            )
        return result

    @router.get("/api/messages/live-location")
    async def get_live_locations(
        with_user: int = Query(..., alias="with", gt=0),
        authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        if with_user == uid:
            raise HTTPException(status_code=400, detail="Нельзя открыть трансляцию с самим собой")
        now = int(time.time())
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            cur = await db.execute(
                """SELECT id,sender_telegram_id,recipient_telegram_id,latitude,longitude,
                          accuracy_m,started_at,updated_at,expires_at
                   FROM live_locations
                   WHERE ((sender_telegram_id=? AND recipient_telegram_id=?)
                       OR (sender_telegram_id=? AND recipient_telegram_id=?))
                     AND stopped_at IS NULL AND expires_at>?
                     AND NOT EXISTS (
                       SELECT 1 FROM blocked_users
                       WHERE (owner_telegram_id=? AND blocked_telegram_id=?)
                          OR (owner_telegram_id=? AND blocked_telegram_id=?))
                   ORDER BY started_at DESC LIMIT 2""",
                (uid, with_user, with_user, uid, now, uid, with_user, with_user, uid),
            )
            # The block check and coordinates share a single SQLite snapshot.
            rows = [dict(row) for row in await cur.fetchall()]
        return {"locations": rows, "count": len(rows)}

    @router.delete("/api/messages/live-location/{live_location_id}")
    async def stop_live_location(
        live_location_id: str,
        authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        if not re.fullmatch(r"[a-f0-9]{32}", live_location_id):
            raise HTTPException(status_code=400, detail="Некорректный ID трансляции геолокации")
        now = int(time.time())
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            cur = await db.execute(
                "SELECT stopped_at,expires_at FROM live_locations WHERE id=? AND (sender_telegram_id=? OR recipient_telegram_id=?)",
                (live_location_id, uid, uid),
            )
            row = await cur.fetchone()
            if row is None:
                raise HTTPException(status_code=404, detail="Активная трансляция геолокации не найдена")
            if row[0] is not None:
                # Idempotent retry after a lost response; do not disclose the coordinates.
                stopped_at = int(row[0])
            elif int(row[1]) <= now:
                raise HTTPException(status_code=404, detail="Активная трансляция геолокации не найдена")
            else:
                stopped_at = now
                await db.execute(
                    """UPDATE live_locations SET stopped_at=?,stopped_by_telegram_id=?,
                              latitude=0,longitude=0,accuracy_m=NULL WHERE id=?""",
                    (now, uid, live_location_id),
                )
            await db.commit()
        return {"status": "stopped", "id": live_location_id, "stopped_at": stopped_at}

    @router.post("/api/messages/album/files/quote/v1", status_code=201)
    @router.post("/api/messages/album/files/v2", status_code=201)
    @router.post("/api/messages/album/files", status_code=201)
    @router.post("/api/messages/album", status_code=201)
    async def send_message_album(
        payload: dict[str, Any],
        request: Request,
        authorization: str | None = Header(default=None),
        idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
    ) -> dict[str, Any]:
        """Create a photo/video album as one atomic send and one push notification."""
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        try:
            recipient_id = int(payload.get("recipient_id", payload.get("to", 0)))
        except (TypeError, ValueError):
            recipient_id = 0
        if recipient_id <= 0:
            raise HTTPException(status_code=400, detail="Укажите корректного получателя")

        allow_documents = album_allow_documents(payload, request)
        raw_media_ids = payload.get("media_ids")
        minimum = 1 if allow_documents else 2
        if not isinstance(raw_media_ids, list) or not minimum <= len(raw_media_ids) <= 10:
            raise HTTPException(status_code=400, detail="Выберите не более 10 файлов")
        media_ids: list[str] = []
        for raw_id in raw_media_ids:
            media_id = str(raw_id or "").strip()
            if not re.fullmatch(r"[a-f0-9]{32}", media_id):
                raise HTTPException(status_code=400, detail="Некорректный ID вложения в альбоме")
            media_ids.append(media_id)
        if not allow_documents and len(set(media_ids)) != len(media_ids):
            raise HTTPException(status_code=400, detail="Альбом не должен содержать повторяющиеся файлы")

        captions, body, caption_entities = album_captions(
            payload, len(media_ids), allow_documents, request.url.path.endswith(("/files/v2", "/files/quote/v1"))
        )
        silent = payload.get("silent", False)
        if not isinstance(silent, bool):
            raise HTTPException(status_code=400, detail="silent должен быть логическим значением")
        now = int(time.time())
        scope = "/api/messages/album"
        if allow_documents:
            scope += "/files"
        descriptor = idempotency_descriptor(scope, payload, idempotency_key)
        album_id = secrets.token_hex(16)
        created_messages: list[dict[str, Any]] = []

        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            await db.execute("BEGIN IMMEDIATE")
            previous = await idempotency_lookup(db, uid, scope, descriptor, now)
            if previous is not None:
                await db.rollback()
                return previous

            recipient_cur = await db.execute(
                "SELECT is_banned FROM accounts WHERE telegram_id=?",
                (recipient_id,),
            )
            recipient = await recipient_cur.fetchone()
            if recipient is None:
                await db.rollback()
                raise HTTPException(status_code=404, detail="Получатель не найден")
            if recipient["is_banned"]:
                await db.rollback()
                raise HTTPException(status_code=403, detail="Получатель заблокирован")
            if recipient_id != uid:
                blocked_cur = await db.execute(
                    """SELECT 1 FROM blocked_users
                       WHERE (owner_telegram_id=? AND blocked_telegram_id=?)
                          OR (owner_telegram_id=? AND blocked_telegram_id=?)
                       LIMIT 1""",
                    (uid, recipient_id, recipient_id, uid),
                )
                if await blocked_cur.fetchone():
                    await db.rollback()
                    raise HTTPException(
                        status_code=403,
                        detail="Нельзя отправить альбом: пользователь находится в чёрном списке",
                    )

            reply_to_id = parse_reply_id(payload)
            quote = parse_message_quote(payload, reply_to_id)
            if reply_to_id:
                await require_reply_target(
                    db,
                    """SELECT 1 FROM messages WHERE id=? AND
                       ((sender_telegram_id=? AND recipient_telegram_id=?) OR
                        (sender_telegram_id=? AND recipient_telegram_id=?))""",
                    (reply_to_id, uid, recipient_id, recipient_id, uid),
                )

            checked_media: list[tuple[str, dict[str, str | None]]] = []
            batch_classes: set[str] = set()
            for media_id in media_ids:
                owned_id = await require_owned_media(db, media_id, uid)
                fields = await media_message_fields(db, owned_id)
                media_type = str(fields.get("media_type") or "").lower()
                if not allow_documents:
                    if not (media_type.startswith("image/") or media_type.startswith("video/")):
                        raise HTTPException(status_code=415, detail="В медиаальбом можно добавлять только фотографии и видео")
                else:
                    media_class = album_media_class(fields)
                    if media_class == "unsupported":
                        raise HTTPException(status_code=415, detail="Голосовые и видеосообщения нельзя включать в набор файлов")
                    batch_classes.add(media_class)
                checked_media.append((media_id, fields))
            # Native clients render document and visual groups differently. Never
            # create a group that would be rendered as the wrong kind of media.
            if len(batch_classes) > 1:
                raise HTTPException(status_code=415, detail="Файлы и фотографии/видео нужно отправить отдельными группами")

            rate_cur = await db.execute(
                "SELECT COUNT(*) FROM messages WHERE sender_telegram_id=? AND created_at>?",
                (uid, now - 60),
            )
            sent_recently = int((await rate_cur.fetchone())[0])
            if sent_recently + len(checked_media) > DM_MESSAGES_PER_MINUTE:
                await db.rollback()
                raise HTTPException(
                    status_code=429,
                    detail="Превышен лимит отправки сообщений для медиаальбома",
                )

            for index, (media_id, media_fields) in enumerate(checked_media):
                item_body = captions[index]
                await require_free_dm(db, uid, recipient_id)
                cur = await db.execute(
                    """INSERT INTO messages
                       (sender_telegram_id,recipient_telegram_id,body,media_id,reply_to_id,
                        media_album_id,media_album_index,media_album_count,created_at)
                       VALUES(?,?,?,?,?,?,?,?,?)""",
                    (
                        uid, recipient_id, item_body, media_id, reply_to_id,
                        album_id, index, len(checked_media), now,
                    ),
                )
                message_id = int(cur.lastrowid)
                if quote is not None:
                    await db.execute("UPDATE messages SET quote_json=? WHERE id=?",
                                     (json.dumps(quote, ensure_ascii=True, separators=(",", ":")), message_id))
                if silent:
                    await db.execute("UPDATE messages SET silent=1 WHERE id=?", (message_id,))
                if caption_entities[index]:
                    await db.execute("UPDATE messages SET entities_json=? WHERE id=?",
                                     (_message_entities_json(caption_entities[index]), message_id))
                await record_event(
                    db, "dm", message_id, "new_message", uid,
                    user_a=uid, user_b=recipient_id,
                )
                created_messages.append({
                    "id": message_id,
                    "sender_id": uid,
                    "recipient_id": recipient_id,
                    "body": item_body,
                    "media_id": media_id,
                    "reply_to_id": reply_to_id,
                    "quote": quote,
                    "media_album_id": album_id,
                    "media_album_index": index,
                    "media_album_count": len(checked_media),
                    **media_fields,
                    "created_at": now,
                })
                if caption_entities[index]:
                    created_messages[-1]["entities"] = caption_entities[index]

            result = {
                "status": "sent",
                "album_id": album_id,
                "count": len(created_messages),
                "first_message_id": created_messages[0]["id"],
                "last_message_id": created_messages[-1]["id"],
                "messages": created_messages,
            }
            await idempotency_store(db, uid, scope, descriptor, result, now)
            await db.commit()

        if recipient_id != uid:
            await deliver_push_notifications(
                [recipient_id],
                str(user.get("display_name") or user.get("username") or "Новое сообщение"),
                f"{'Файлы' if batch_classes == {'document'} else 'Медиаальбом'} · {len(created_messages)} вложений",
                {
                    "scope": "dm",
                    "chat_id": str(uid),
                    "message_id": str(created_messages[-1]["id"]),
                    "media_album_id": album_id,
                    "silent": "1" if silent else "0",
                },
            )
        return result


    @router.post("/api/messages/schedule/v2", status_code=201)
    @router.post("/api/messages/schedule", status_code=201)
    async def schedule_direct_message(
        payload: dict[str, Any],
        request: Request,
        authorization: str | None = Header(default=None),
        idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        if "entities" in payload and not request.url.path.endswith("/v2"):
            raise HTTPException(status_code=400, detail="Используйте версию v2 для форматирования")
        try:
            recipient_id = int(payload.get("recipient_id", 0))
        except (TypeError, ValueError):
            recipient_id = 0
        if recipient_id <= 0:
            raise HTTPException(status_code=400, detail="Укажите корректного получателя")
        body_value = payload.get("body")
        if not isinstance(body_value, str):
            raise HTTPException(status_code=400, detail="Укажите текст сообщения")
        body, entities = (_message_body_and_entities({"body": body_value, "entities": payload.get("entities", [])})
                          if request.url.path.endswith("/v2") else (_message_body(body_value), []))
        scheduled_at = payload.get("scheduled_at")
        if isinstance(scheduled_at, bool) or not isinstance(scheduled_at, int):
            raise HTTPException(status_code=400, detail="scheduled_at должен быть Unix timestamp")
        repeat_interval = payload.get("repeat_interval_seconds", 0)
        if (
            isinstance(repeat_interval, bool)
            or not isinstance(repeat_interval, int)
            or repeat_interval not in (0, 86400, 604800)
        ):
            raise HTTPException(
                status_code=400,
                detail="repeat_interval_seconds: 0, 86400 или 604800",
            )
        silent = payload.get("silent", False)
        if not isinstance(silent, bool):
            raise HTTPException(status_code=400, detail="silent должен быть логическим значением")
        time_zone = payload.get("time_zone", "UTC")
        if not isinstance(time_zone, str) or not time_zone.strip() or len(time_zone) > 64:
            raise HTTPException(status_code=400, detail="time_zone должен содержать IANA-идентификатор часового пояса")
        time_zone = time_zone.strip()
        try:
            ZoneInfo(time_zone)
        except (ZoneInfoNotFoundError, ValueError):
            raise HTTPException(status_code=400, detail="Неизвестный часовой пояс")
        now = int(time.time())
        if scheduled_at < now + 10:
            raise HTTPException(status_code=400, detail="Отправка должна быть запланирована минимум через 10 секунд")
        if scheduled_at > now + 30 * 24 * 60 * 60:
            raise HTTPException(status_code=400, detail="Нельзя запланировать отправку более чем на 30 дней")
        scope = request.url.path
        descriptor = idempotency_descriptor(scope, payload, idempotency_key)
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            previous = await idempotency_lookup(db, uid, scope, descriptor, now)
            if previous is not None:
                await db.rollback()
                return previous
            cur = await db.execute(
                "SELECT is_banned FROM accounts WHERE telegram_id=?",
                (recipient_id,),
            )
            recipient = await cur.fetchone()
            if recipient is None:
                await db.rollback()
                raise HTTPException(status_code=404, detail="Получатель не найден")
            if recipient[0]:
                await db.rollback()
                raise HTTPException(status_code=403, detail="Получатель заблокирован")
            if recipient_id != uid:
                cur = await db.execute(
                    """SELECT 1 FROM blocked_users
                       WHERE (owner_telegram_id=? AND blocked_telegram_id=?)
                          OR (owner_telegram_id=? AND blocked_telegram_id=?)
                       LIMIT 1""",
                    (uid, recipient_id, recipient_id, uid),
                )
                if await cur.fetchone():
                    await db.rollback()
                    raise HTTPException(status_code=403, detail="Нельзя запланировать сообщение: пользователь находится в чёрном списке")
            await require_free_dm(db, uid, recipient_id)
            cur = await db.execute(
                """INSERT INTO scheduled_messages
                   (sender_telegram_id,recipient_telegram_id,body,scheduled_at,
                    repeat_interval_seconds,created_at,silent,time_zone,entities_json)
                   VALUES(?,?,?,?,?,?,?,?,?)""",
                (uid, recipient_id, body, scheduled_at, repeat_interval, now, int(silent), time_zone, _message_entities_json(entities)),
            )
            scheduled_id = int(cur.lastrowid)
            if request.url.path.endswith("/v2"):
                if scheduled_id > 1073741823:
                    raise HTTPException(status_code=503, detail="Превышен диапазон ID отложенных сообщений")
                await record_event(db, "scheduled", scheduled_id * 2, "scheduled_changed", uid, chat_id=recipient_id)
            result = {
                "id": scheduled_id,
                "status": "pending",
                "sender_id": uid,
                "recipient_id": recipient_id,
                "body": body,
                "scheduled_at": scheduled_at,
                "repeat_interval_seconds": repeat_interval,
                "silent": silent,
                "time_zone": time_zone,
                "created_at": now,
            }
            if request.url.path.endswith("/v2"):
                result["entities"] = entities
            await idempotency_store(db, uid, scope, descriptor, result, now)
            await db.commit()
        return result

    @router.post("/api/messages/when-online/v2", status_code=201)
    @router.post("/api/messages/when-online", status_code=201)
    async def schedule_message_when_online(
        payload: dict[str, Any],
        request: Request,
        authorization: str | None = Header(default=None),
        idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        if "entities" in payload and not request.url.path.endswith("/v2"):
            raise HTTPException(status_code=400, detail="Используйте версию v2 для форматирования")
        try:
            recipient_id = int(payload.get("recipient_id", 0))
        except (TypeError, ValueError):
            recipient_id = 0
        if recipient_id <= 0 or recipient_id == uid:
            raise HTTPException(status_code=400, detail="Укажите другого получателя")
        body_value = payload.get("body")
        if not isinstance(body_value, str):
            raise HTTPException(status_code=400, detail="Укажите текст сообщения")
        body, entities = (_message_body_and_entities({"body": body_value, "entities": payload.get("entities", [])})
                          if request.url.path.endswith("/v2") else (_message_body(body_value), []))
        silent = payload.get("silent", False)
        if not isinstance(silent, bool):
            raise HTTPException(status_code=400, detail="silent должен быть логическим значением")
        now = int(time.time())
        scope = request.url.path
        descriptor = idempotency_descriptor(scope, payload, idempotency_key)
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            previous = await idempotency_lookup(db, uid, scope, descriptor, now)
            if previous is not None:
                await db.rollback()
                return previous
            cur = await db.execute(
                "SELECT is_banned FROM accounts WHERE telegram_id=?", (recipient_id,)
            )
            recipient = await cur.fetchone()
            if recipient is None:
                await db.rollback()
                raise HTTPException(status_code=404, detail="Получатель не найден")
            if recipient[0]:
                await db.rollback()
                raise HTTPException(status_code=403, detail="Получатель заблокирован")
            cur = await db.execute(
                """SELECT 1 FROM blocked_users
                   WHERE (owner_telegram_id=? AND blocked_telegram_id=?)
                      OR (owner_telegram_id=? AND blocked_telegram_id=?) LIMIT 1""",
                (uid, recipient_id, recipient_id, uid),
            )
            if await cur.fetchone():
                await db.rollback()
                raise HTTPException(status_code=403, detail="Нельзя отправить сообщение: пользователь находится в чёрном списке")
            await require_free_dm(db, uid, recipient_id)
            cur = await db.execute(
                "SELECT COUNT(*) FROM online_scheduled_messages WHERE sender_telegram_id=? AND status='pending'",
                (uid,),
            )
            if int((await cur.fetchone())[0]) >= 100:
                await db.rollback()
                raise HTTPException(status_code=429, detail="Слишком много сообщений ожидают появления получателей онлайн")
            cur = await db.execute(
                """INSERT INTO online_scheduled_messages
                   (sender_telegram_id,recipient_telegram_id,body,silent,created_at,entities_json)
                   VALUES(?,?,?,?,?,?)""",
                (uid, recipient_id, body, int(silent), now, _message_entities_json(entities)),
            )
            scheduled_id = int(cur.lastrowid)
            if request.url.path.endswith("/v2"):
                if scheduled_id > 1073741823:
                    raise HTTPException(status_code=503, detail="Превышен диапазон ID отложенных сообщений")
                await record_event(db, "scheduled", scheduled_id * 2 + 1, "scheduled_changed", uid, chat_id=recipient_id)
            result = {
                "id": scheduled_id,
                "status": "pending",
                "trigger": "when_online",
                "sender_id": uid,
                "recipient_id": recipient_id,
                "body": body,
                "silent": silent,
                "created_at": now,
            }
            if request.url.path.endswith("/v2"):
                result["entities"] = entities
            await idempotency_store(db, uid, scope, descriptor, result, now)
            await db.commit()
        return result

