    @router.get("/api/messages/scheduled/native/v1")
    async def native_scheduled_list(peer: int = Query(alias="with", gt=0),
                                    authorization: str | None = Header(default=None)) -> dict[str, Any]:
        uid = int((await current_user(authorization))["telegram_id"])
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            await db.execute("BEGIN")
            cur = await db.execute("""SELECT id,recipient_telegram_id AS recipient_id,body,scheduled_at,
                    repeat_interval_seconds,silent,created_at,status,error,entities_json,0 AS online
                FROM scheduled_messages WHERE sender_telegram_id=? AND recipient_telegram_id=?
                  AND status IN ('pending','failed') AND id<=1073741823
                UNION ALL
                SELECT id,recipient_telegram_id AS recipient_id,body,2147483646 AS scheduled_at,
                    0 AS repeat_interval_seconds,silent,created_at,status,error,entities_json,1 AS online
                FROM online_scheduled_messages WHERE sender_telegram_id=? AND recipient_telegram_id=?
                  AND status IN ('pending','failed') AND id<=1073741823
                ORDER BY scheduled_at,id LIMIT 1000""", (uid, peer, uid, peer))
            rows = [dict(row) for row in await cur.fetchall()]
        for row in rows:
            row["native_id"] = int(row["id"]) * 2 + int(row["online"])
            _add_message_entities(row)
        return {"scheduled_messages": rows, "count": len(rows)}

    @router.post("/api/messages/scheduled/cancel/native/v1")
    async def native_cancel_scheduled(payload: dict[str, Any], authorization: str | None = Header(default=None)) -> dict[str, Any]:
        uid = int((await current_user(authorization))["telegram_id"])
        peer, ids = payload.get("peer_id"), payload.get("ids")
        if isinstance(peer, bool) or not isinstance(peer, int) or not 0 < peer <= 9223372036854775807:
            raise HTTPException(status_code=400, detail="Некорректный собеседник")
        if not isinstance(ids, list) or not 1 <= len(ids) <= 200 or any(
            isinstance(i, bool) or not isinstance(i, int) or i < 2 or i > 2147483647 for i in ids
        ) or len(set(ids)) != len(ids):
            raise HTTPException(status_code=400, detail="Некорректный список сообщений")
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            for native_id in ids:
                table = "online_scheduled_messages" if native_id % 2 else "scheduled_messages"
                cur = await db.execute(f"SELECT status FROM {table} WHERE id=? AND sender_telegram_id=? AND recipient_telegram_id=?",
                                       (native_id // 2, uid, peer))
                row = await cur.fetchone()
                if row is None or row[0] not in ("pending", "failed", "cancelled"):
                    raise HTTPException(status_code=409, detail="Сообщение уже отправлено или недоступно")
                if row[0] != "cancelled":
                    await db.execute(f"UPDATE {table} SET status='cancelled' WHERE id=?", (native_id // 2,))
                    await record_event(db, "scheduled", native_id, "scheduled_removed", uid, chat_id=peer)
            await db.commit()
        return {"cancelled": ids}

    @router.post("/api/messages/scheduled/send-now/native/v1")
    async def native_send_scheduled_now(payload: dict[str, Any], authorization: str | None = Header(default=None)) -> dict[str, Any]:
        """Send selected private text jobs exactly once, including after an HTTP retry.

        Sending a recurring job now terminates that job rather than leaving a
        surprising future recurrence behind. The entire batch is transactional.
        """
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        peer, ids = payload.get("peer_id"), payload.get("ids")
        if isinstance(peer, bool) or not isinstance(peer, int) or not 0 < peer <= 9223372036854775807:
            raise HTTPException(status_code=400, detail="Некорректный собеседник")
        if not isinstance(ids, list) or not 1 <= len(ids) <= 200 or any(
            isinstance(i, bool) or not isinstance(i, int) or i < 2 or i > 2147483647 for i in ids
        ) or len(set(ids)) != len(ids):
            raise HTTPException(status_code=400, detail="Некорректный список сообщений")
        now = int(time.time())
        queued_push = False
        results: list[dict[str, Any]] = []
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            await db.execute("BEGIN IMMEDIATE")
            jobs = []
            for native_id in ids:
                table = "online_scheduled_messages" if native_id % 2 else "scheduled_messages"
                cur = await db.execute(f"""SELECT status,message_id,body,silent,entities_json
                    FROM {table} WHERE id=? AND sender_telegram_id=? AND recipient_telegram_id=?""",
                    (native_id // 2, uid, peer))
                row = await cur.fetchone()
                if row is None or row["status"] not in ("pending", "failed", "sent"):
                    raise HTTPException(status_code=409, detail="Сообщение отменено или недоступно")
                jobs.append((native_id, table, row))
            pending = sum(1 for _, _, row in jobs if row["status"] != "sent")
            if pending:
                cur = await db.execute("SELECT is_banned FROM accounts WHERE telegram_id=?", (peer,))
                recipient = await cur.fetchone()
                if recipient is None or recipient[0]:
                    raise HTTPException(status_code=403, detail="Получатель недоступен")
                if peer != uid:
                    cur = await db.execute("""SELECT 1 FROM blocked_users
                        WHERE (owner_telegram_id=? AND blocked_telegram_id=?)
                           OR (owner_telegram_id=? AND blocked_telegram_id=?) LIMIT 1""", (uid, peer, peer, uid))
                    if await cur.fetchone():
                        raise HTTPException(status_code=403, detail="Пользователь находится в чёрном списке")
                cur = await db.execute("SELECT COUNT(*) FROM messages WHERE sender_telegram_id=? AND created_at>?", (uid, now - 60))
                if int((await cur.fetchone())[0]) + pending > DM_MESSAGES_PER_MINUTE:
                    raise HTTPException(status_code=429, detail="Превышен лимит отправки сообщений")
            for native_id, table, row in jobs:
                if row["status"] == "sent":
                    # Do not recreate a message if it was deleted after delivery.
                    cur = await db.execute("""SELECT id,body,created_at,silent,entities_json FROM messages
                        WHERE id=? AND sender_telegram_id=? AND recipient_telegram_id=?""", (row["message_id"], uid, peer))
                    message = await cur.fetchone()
                    if message is None:
                        raise HTTPException(status_code=409, detail="Отправленное сообщение больше недоступно")
                    result = dict(message)
                else:
                    await require_free_dm(db, uid, peer)
                    cur = await db.execute("""INSERT INTO messages(sender_telegram_id,recipient_telegram_id,body,created_at,silent,entities_json)
                        VALUES(?,?,?,?,?,?)""", (uid, peer, row["body"], now, row["silent"], row["entities_json"]))
                    message_id = int(cur.lastrowid)
                    await db.execute(f"UPDATE {table} SET status='sent',message_id=?,error='' WHERE id=?", (message_id, native_id // 2))
                    await record_event(db, "dm", message_id, "new_message", uid, user_a=uid, user_b=peer)
                    await record_event(db, "scheduled", native_id, "scheduled_removed", uid, chat_id=peer)
                    if peer != uid:
                        queued_push |= await enqueue_push(db, uid, peer, str(user.get("display_name") or user.get("username") or "Новое сообщение"),
                            str(row["body"]), {"scope": "dm", "chat_id": str(uid), "message_id": str(message_id),
                            "silent": "1" if row["silent"] else "0"}, now)
                    result = {"id": message_id, "body": str(row["body"]), "created_at": now,
                              "silent": int(row["silent"]), "entities_json": row["entities_json"]}
                result["sender_id"] = uid
                result["recipient_id"] = peer
                result["scheduled_native_id"] = native_id
                _add_message_entities(result)
                results.append(result)
            await db.commit()
        if queued_push:
            push_wakeup.set()
        return {"messages": results}

    @router.patch("/api/messages/scheduled/{scheduled_id}")
    async def reschedule_message(
        scheduled_id: int,
        payload: dict[str, Any],
        authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        scheduled_at = payload.get("scheduled_at")
        if type(scheduled_at) is not int:
            raise HTTPException(status_code=400, detail="scheduled_at должен быть Unix timestamp")
        if not 0 < scheduled_id <= 1073741823:
            raise HTTPException(status_code=404, detail="Отложенное сообщение не найдено")
        repeat = payload.get("repeat_interval_seconds")
        if "repeat_interval_seconds" in payload and (type(repeat) is not int or repeat not in (0, 86400, 604800)):
            raise HTTPException(status_code=400, detail="repeat_interval_seconds: 0, 86400 или 604800")
        peer = payload.get("peer_id", 0)
        if type(peer) is not int or not 0 <= peer <= 2**63 - 1:
            raise HTTPException(status_code=400, detail="Некорректный peer_id")
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            await db.execute("BEGIN IMMEDIATE")
            now = int(time.time())
            if not now + 10 <= scheduled_at <= now + 30 * 86400:
                raise HTTPException(status_code=400, detail="Укажите время отправки от 10 секунд до 30 дней вперёд")
            cur = await db.execute(
                """UPDATE scheduled_messages SET scheduled_at=?, repeat_interval_seconds=COALESCE(?,repeat_interval_seconds)
                   WHERE id=? AND sender_telegram_id=? AND status='pending'
                     AND (?=0 OR recipient_telegram_id=?)
                   RETURNING id, recipient_telegram_id AS recipient_id, body, scheduled_at,
                             status, silent, repeat_interval_seconds, entities_json""",
                (scheduled_at, repeat, scheduled_id, uid, peer, peer),
            )
            task = await cur.fetchone()
            await cur.close()
            if task is None:
                raise HTTPException(status_code=404, detail="Отложенное сообщение не найдено или уже обработано")
            await record_event(db, "scheduled", scheduled_id * 2, "scheduled_changed", uid, chat_id=int(task["recipient_id"]))
            await db.commit()
        result = dict(task)
        result["native_id"] = scheduled_id * 2
        _add_message_entities(result)
        return result

    @router.delete("/api/messages/scheduled/{scheduled_id}")
    async def cancel_scheduled_message(
        scheduled_id: int,
        authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            cur = await db.execute("SELECT recipient_telegram_id FROM scheduled_messages WHERE id=? AND sender_telegram_id=? AND status='pending'", (scheduled_id, uid))
            task = await cur.fetchone()
            cur = await db.execute(
                """UPDATE scheduled_messages SET status='cancelled'
                   WHERE id=? AND sender_telegram_id=? AND status='pending'""",
                (scheduled_id, uid),
            )
            if cur.rowcount != 1:
                await db.rollback()
                raise HTTPException(status_code=404, detail="Отложенное сообщение не найдено или уже обработано")
            if task and scheduled_id <= 1073741823:
                await record_event(db, "scheduled", scheduled_id * 2, "scheduled_removed", uid, chat_id=int(task[0]))
            await db.commit()
        return {"id": scheduled_id, "status": "cancelled"}


    @router.post("/api/messages/gift", status_code=201)
    async def send_gift_message(
        payload: dict[str, Any],
        authorization: str | None = Header(default=None),
        idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
    ) -> dict[str, Any]:
        """Transfer a WaysGram-owned gift and persist its collectible snapshot in a DM."""
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        try:
            recipient_id = int(payload.get("recipient_id", 0))
        except (TypeError, ValueError):
            recipient_id = 0
        serial = str(payload.get("serial_number") or "").strip().upper()
        if recipient_id <= 0 or not GIFT_SERIAL_RE.fullmatch(serial):
            raise HTTPException(status_code=400, detail="Укажите получателя и корректный серийный номер подарка")
        if recipient_id == uid:
            raise HTTPException(status_code=400, detail="Нельзя отправить подарок самому себе")
        caption_value = str(payload.get("body") or "").strip()
        body = _message_body(caption_value) if caption_value else "Подарок WaysGram"
        now = int(time.time())
        scope = "/api/messages/gift"
        descriptor = idempotency_descriptor(scope, payload, idempotency_key)
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            await db.execute("BEGIN IMMEDIATE")
            previous = await idempotency_lookup(db, uid, scope, descriptor, now)
            if previous is not None:
                await db.rollback()
                return previous
            cur = await db.execute(
                "SELECT is_banned FROM accounts WHERE telegram_id=?",
                (recipient_id,),
            )
            recipient = await cur.fetchone()
            if recipient is None:
                await db.rollback()
                raise HTTPException(status_code=404, detail="Получатель не найден")
            if recipient["is_banned"]:
                await db.rollback()
                raise HTTPException(status_code=403, detail="Получатель заблокирован")
            await require_gift_delivery_allowed(db, uid, recipient_id)
            cur = await db.execute(
                """SELECT id,gift_name,telegram_gift_id,upgrade_level,attributes_json,
                          (SELECT unique_num FROM gift_unique_numbers n
                           WHERE n.serial_number=user_gifts.serial_number) AS unique_num
                   FROM user_gifts WHERE serial_number=? AND owner_telegram_id=?""",
                (serial, uid),
            )
            gift = await cur.fetchone()
            if gift is None:
                await db.rollback()
                raise HTTPException(status_code=404, detail="Подарок не найден в вашем инвентаре")
            await require_gift_type(db, recipient_id, gift["upgrade_level"], gift["attributes_json"])
            cur = await db.execute(
                "SELECT 1 FROM gift_market_listings WHERE serial_number=? AND status='active'",
                (serial,),
            )
            if await cur.fetchone():
                await db.rollback()
                raise HTTPException(status_code=409, detail="Сначала снимите подарок с продажи")
            cur = await db.execute(
                "SELECT 1 FROM gift_collectible_auctions WHERE serial_number=? AND status='active'",
                (serial,),
            )
            if await cur.fetchone():
                await db.rollback()
                raise HTTPException(status_code=409, detail="Сначала отмените аукцион подарка")
            cur = await db.execute(
                "SELECT COUNT(*) FROM messages WHERE sender_telegram_id=? AND created_at>?",
                (uid, now - 60),
            )
            if int((await cur.fetchone())[0]) >= DM_MESSAGES_PER_MINUTE:
                await db.rollback()
                raise HTTPException(status_code=429, detail="Превышен лимит отправки сообщений")
            try:
                attributes = json.loads(str(gift["attributes_json"] or "{}"))
            except (TypeError, ValueError):
                attributes = {}
            if not isinstance(attributes, dict):
                attributes = {}
            attributes_json = json.dumps(attributes, ensure_ascii=False, separators=(",", ":"))
            cur = await db.execute(
                "UPDATE user_gifts SET owner_telegram_id=? WHERE id=? AND owner_telegram_id=?",
                (recipient_id, int(gift["id"]), uid),
            )
            if cur.rowcount != 1:
                await db.rollback()
                raise HTTPException(status_code=409, detail="Владение подарком уже изменилось")
            await apply_gift_autosave(db, serial, recipient_id, uid)
            await require_free_dm(db, uid, recipient_id)
            cur = await db.execute(
                """INSERT INTO messages
                   (sender_telegram_id,recipient_telegram_id,body,created_at)
                   VALUES(?,?,?,?)""",
                (uid, recipient_id, body, now),
            )
            message_id = int(cur.lastrowid)
            gift_name = str(gift["gift_name"])
            telegram_gift_id = str(gift["telegram_gift_id"] or "")
            upgrade_level = int(gift["upgrade_level"] or 0)
            await db.execute(
                """INSERT INTO message_gifts
                   (message_id,serial_number,gift_name,telegram_gift_id,upgrade_level,attributes_json)
                   VALUES(?,?,?,?,?,?)""",
                (message_id, serial, gift_name, telegram_gift_id, upgrade_level, attributes_json),
            )
            await db.execute(
                """INSERT INTO gift_transactions
                   (event_type,serial_number,gift_name,from_telegram_id,to_telegram_id,created_at,message_id)
                   VALUES('chat_send',?,?,?,?,?,?)""",
                (serial, gift_name, uid, recipient_id, now, message_id),
            )
            await record_event(
                db, "dm", message_id, "new_message", uid,
                user_a=uid, user_b=recipient_id,
            )
            result = {
                "id": message_id,
                "status": "sent",
                "type": "gift",
                "sender_id": uid,
                "recipient_id": recipient_id,
                "body": body,
                "gift_serial_number": serial,
                "gift_name": gift_name,
                "gift_telegram_gift_id": telegram_gift_id,
                "gift_upgrade_level": upgrade_level,
                "gift_unique_num": int(gift["unique_num"] or 0),
                "gift_instance_id": int(gift["id"]),
                "gift_attributes": attributes,
                "created_at": now,
            }
            await idempotency_store(db, uid, scope, descriptor, result, now)
            queued_push = await enqueue_push(
                db, uid, recipient_id, str(user.get("display_name") or user.get("username") or "Новый подарок"),
                f"Подарок WaysGram: {gift_name}",
                {"scope": "dm", "chat_id": str(uid), "message_id": str(message_id), "type": "gift"}, now,
            )
            await db.commit()
        if queued_push:
            push_wakeup.set()
        return result

    @router.post("/api/forward", status_code=201)
    async def forward_batch(
        payload: dict[str, Any],
        authorization: str | None = Header(default=None),
        idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
    ) -> dict[str, Any]:
        """Atomically forward text, files and static locations between authorized chats."""
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        source_scope, target_scope = payload.get("source_scope"), payload.get("target_scope")
        source_peer, target_peer = payload.get("source_peer_id"), payload.get("target_peer_id")
        ids = payload.get("message_ids")
        if source_scope not in ("dm", "group", "channel") or target_scope not in ("dm", "group", "channel"):
            raise HTTPException(status_code=400, detail="Некорректный тип чата")
        if (isinstance(source_peer, bool) or not isinstance(source_peer, int) or source_peer <= 0
                or isinstance(target_peer, bool) or not isinstance(target_peer, int) or target_peer <= 0):
            raise HTTPException(status_code=400, detail="Некорректный идентификатор чата")
        if (not isinstance(ids, list) or not 1 <= len(ids) <= 20
                or any(isinstance(v, bool) or not isinstance(v, int) or v <= 0 for v in ids)
                or len(set(ids)) != len(ids)):
            raise HTTPException(status_code=400, detail="Выберите от 1 до 20 разных сообщений")
        for key in ("silent", "drop_author", "drop_media_captions"):
            if not isinstance(payload.get(key, False), bool):
                raise HTTPException(status_code=400, detail=f"{key} должен быть логическим значением")
        silent, drop_author, drop_captions = (payload.get(key, False) for key in
                                              ("silent", "drop_author", "drop_media_captions"))
        scope = "/api/forward"
        descriptor = idempotency_descriptor(scope, payload, idempotency_key)
        now = int(time.time())
        notifications: list[int] = []
        queued_push = False
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            await db.execute("BEGIN IMMEDIATE")
            prior = await idempotency_lookup(db, uid, scope, descriptor, now)
            if prior is not None:
                # Cached responses may contain private contact cards: do not reveal
                # them after source access or destination rights were revoked.
                if source_scope == "group":
                    await require_group_member(db, source_peer, uid)
                elif source_scope == "channel":
                    cur = await db.execute("""SELECT 1 FROM channels c WHERE c.id=? AND NOT EXISTS(SELECT 1 FROM channel_bans cb WHERE cb.channel_id=c.id AND cb.telegram_id=? AND (cb.until_date=0 OR cb.until_date>CAST(strftime('%s','now') AS INTEGER))) AND
                        (c.is_public=1 OR c.owner_telegram_id=? OR EXISTS(SELECT 1 FROM channel_admins a
                        WHERE a.channel_id=c.id AND a.telegram_id=?) OR EXISTS(SELECT 1 FROM active_channel_members m
                        WHERE m.channel_id=c.id AND m.telegram_id=?))""", (source_peer, uid, uid, uid, uid))
                    if await cur.fetchone() is None:
                        raise HTTPException(status_code=403, detail="Нет доступа к исходному каналу")
                for source_id in ids:
                    if source_scope == "dm":
                        cur = await db.execute("""SELECT 1 FROM messages m WHERE m.id=? AND
                            ((m.sender_telegram_id=? AND m.recipient_telegram_id=?) OR
                             (m.sender_telegram_id=? AND m.recipient_telegram_id=?)) AND NOT EXISTS
                            (SELECT 1 FROM message_hidden_for h WHERE h.message_id=m.id AND h.telegram_id=?)""",
                            (source_id, uid, source_peer, source_peer, uid, uid))
                    elif source_scope == "group":
                        cur = await db.execute("SELECT 1 FROM group_messages WHERE id=? AND group_id=?", (source_id, source_peer))
                    else:
                        cur = await db.execute("SELECT 1 FROM channel_messages WHERE id=? AND channel_id=?", (source_id, source_peer))
                    if await cur.fetchone() is None:
                        raise HTTPException(status_code=404, detail="Исходное сообщение не найдено")
                if target_scope == "group":
                    await require_group_member(db, target_peer, uid)
                    await require_group_can_send(db, target_peer, uid)
                elif target_scope == "channel":
                    cur = await db.execute("""SELECT 1 FROM channels c WHERE c.id=? AND
                        (c.owner_telegram_id=? OR EXISTS(SELECT 1 FROM channel_admins a
                        WHERE a.channel_id=c.id AND a.telegram_id=? AND (a.rights & 1) != 0))""", (target_peer, uid, uid))
                    if await cur.fetchone() is None:
                        raise HTTPException(status_code=403, detail="Публиковать может только администратор канала")
                else:
                    cur = await db.execute("SELECT is_banned FROM accounts WHERE telegram_id=?", (target_peer,))
                    target = await cur.fetchone()
                    if target is None:
                        raise HTTPException(status_code=404, detail="Получатель не найден")
                    if target[0]:
                        raise HTTPException(status_code=403, detail="Получатель заблокирован")
                    cur = await db.execute("""SELECT 1 FROM blocked_users WHERE
                        (owner_telegram_id=? AND blocked_telegram_id=?) OR
                        (owner_telegram_id=? AND blocked_telegram_id=?) LIMIT 1""", (uid, target_peer, target_peer, uid))
                    if await cur.fetchone():
                        raise HTTPException(status_code=403, detail="Пересылка заблокирована")
                await db.rollback()
                return prior

            # All access checks share the write transaction with the copies, so
            # leaving a group or changing channel privacy cannot race a forward.
            if source_scope == "group":
                await require_group_member(db, source_peer, uid)
            elif source_scope == "channel":
                cur = await db.execute("""SELECT 1 FROM channels c WHERE c.id=? AND NOT EXISTS(SELECT 1 FROM channel_bans cb WHERE cb.channel_id=c.id AND cb.telegram_id=? AND (cb.until_date=0 OR cb.until_date>CAST(strftime('%s','now') AS INTEGER))) AND
                    (c.is_public=1 OR c.owner_telegram_id=? OR EXISTS(
                        SELECT 1 FROM channel_admins a WHERE a.channel_id=c.id AND a.telegram_id=?) OR EXISTS(
                        SELECT 1 FROM active_channel_members m WHERE m.channel_id=c.id AND m.telegram_id=?))""",
                    (source_peer, uid, uid, uid, uid))
                if await cur.fetchone() is None:
                    raise HTTPException(status_code=403, detail="Нет доступа к исходному каналу")

            member = None
            if target_scope == "dm":
                cur = await db.execute("SELECT is_banned FROM accounts WHERE telegram_id=?", (target_peer,))
                target = await cur.fetchone()
                if target is None:
                    raise HTTPException(status_code=404, detail="Получатель не найден")
                if target[0]:
                    raise HTTPException(status_code=403, detail="Получатель заблокирован")
                cur = await db.execute("""SELECT 1 FROM blocked_users
                    WHERE (owner_telegram_id=? AND blocked_telegram_id=?) OR
                          (owner_telegram_id=? AND blocked_telegram_id=?) LIMIT 1""",
                    (uid, target_peer, target_peer, uid))
                if await cur.fetchone():
                    raise HTTPException(status_code=403, detail="Пересылка заблокирована")
                table, sender_col, limit = "messages", "sender_telegram_id", DM_MESSAGES_PER_MINUTE
            elif target_scope == "group":
                member = await require_group_member(db, target_peer, uid)
                await require_group_can_send(db, target_peer, uid)
                await require_group_anti_spam(db, target_peer, uid, member, now, units=len(ids))
                table, sender_col, limit = "group_messages", "sender_telegram_id", DM_MESSAGES_PER_MINUTE
                cur = await db.execute("SELECT slow_mode_seconds FROM chat_groups WHERE id=?", (target_peer,))
                slow = int((await cur.fetchone())[0])
                if slow and member["role"] not in ("owner", "admin") and not await group_boost_bypasses_slow_mode(db, target_peer, uid):
                    if len(ids) > 1:
                        raise HTTPException(status_code=429, detail="Медленный режим: пересылайте сообщения по одному")
                    cur = await db.execute("""SELECT created_at FROM group_messages WHERE group_id=? AND sender_telegram_id=?
                        ORDER BY id DESC LIMIT 1""", (target_peer, uid))
                    previous = await cur.fetchone()
                    if previous and now - int(previous[0]) < slow:
                        remaining = slow - max(0, now - int(previous[0]))
                        raise HTTPException(status_code=429, detail="Действует медленный режим", headers={"Retry-After": str(remaining)})
            else:
                cur = await db.execute("""SELECT 1 FROM channels c WHERE c.id=? AND
                    (c.owner_telegram_id=? OR EXISTS(SELECT 1 FROM channel_admins a
                     WHERE a.channel_id=c.id AND a.telegram_id=? AND (a.rights & 1) != 0))""", (target_peer, uid, uid))
                if await cur.fetchone() is None:
                    raise HTTPException(status_code=403, detail="Публиковать может только администратор канала")
                table, sender_col, limit = "channel_messages", "author_telegram_id", CHANNEL_POSTS_PER_MINUTE
            cur = await db.execute(f"SELECT COUNT(*) FROM {table} WHERE {sender_col}=? AND created_at>?", (uid, now - 60))
            if int((await cur.fetchone())[0]) + len(ids) > limit:
                raise HTTPException(status_code=429, detail="Превышен лимит отправки сообщений")

            sources = []
            for mid in ids:
                if source_scope == "dm":
                    cur = await db.execute("""SELECT m.*,m.sender_telegram_id AS author_id FROM messages m
                        WHERE m.id=? AND ((m.sender_telegram_id=? AND m.recipient_telegram_id=?) OR
                        (m.sender_telegram_id=? AND m.recipient_telegram_id=?)) AND NOT EXISTS
                        (SELECT 1 FROM message_hidden_for h WHERE h.message_id=m.id AND h.telegram_id=?)""",
                        (mid, uid, source_peer, source_peer, uid, uid))
                elif source_scope == "group":
                    cur = await db.execute("SELECT *,sender_telegram_id AS author_id FROM group_messages WHERE id=? AND group_id=? AND topic_id IS NULL AND send_as_id IS NULL", (mid, source_peer))
                else:
                    cur = await db.execute("SELECT *,author_telegram_id AS author_id FROM channel_messages WHERE id=? AND channel_id=?", (mid, source_peer))
                row = await cur.fetchone()
                if row is None:
                    raise HTTPException(status_code=404, detail="Исходное сообщение не найдено")
                item = dict(row)
                if target_scope == "group":
                    await require_group_can_send(db, target_peer, uid, item.get("media_id"))
                if source_scope == "dm":
                    cur = await db.execute("SELECT 1 FROM message_gifts WHERE message_id=?", (mid,))
                    if await cur.fetchone():
                        raise HTTPException(status_code=400, detail="Этот тип вложения пока нельзя переслать")
                    cur = await db.execute("SELECT latitude,longitude,label,venue_json FROM message_locations WHERE message_id=?", (mid,))
                else:
                    cur = await db.execute("SELECT latitude,longitude,label,venue_json FROM message_forward_locations WHERE scope=? AND message_id=?", (source_scope, mid))
                location = await cur.fetchone()
                item["forward_location"] = tuple(location) if location else None
                contact_columns = "contact_name,contact_phone,contact_email,contact_first_name,contact_last_name,contact_vcard"
                if source_scope == "dm":
                    cur = await db.execute(f"SELECT {contact_columns} FROM message_contacts WHERE message_id=?", (mid,))
                else:
                    cur = await db.execute(f"SELECT {contact_columns} FROM message_scoped_contacts WHERE scope=? AND message_id=?", (source_scope, mid))
                contact = await cur.fetchone()
                item["forward_contact"] = tuple(contact) if contact else None
                if contact and (location or item.get("media_id")):
                    raise HTTPException(status_code=400, detail="Нельзя переслать несовместимые вложения")
                cur = await db.execute("SELECT from_name,from_date FROM message_forward_sources WHERE scope=? AND message_id=?", (source_scope, mid))
                prior_source = await cur.fetchone()
                if prior_source:
                    from_name, from_date = str(prior_source[0]), int(prior_source[1])
                elif source_scope == "channel":
                    cur = await db.execute("SELECT title FROM channels WHERE id=?", (source_peer,))
                    from_name, from_date = str((await cur.fetchone())[0]), int(item["created_at"])
                else:
                    author_id = item.get("forwarded_from_telegram_id") or item["author_id"]
                    cur = await db.execute("SELECT COALESCE(NULLIF(display_name,''),NULLIF(username,''),'Пользователь') FROM accounts WHERE telegram_id=?", (author_id,))
                    author = await cur.fetchone()
                    from_name, from_date = str(author[0]) if author else "Пользователь", int(item["created_at"])
                item["forward_link_author"] = (
                    item.get("forwarded_from_telegram_id") or (item["author_id"] if not prior_source else None)
                ) if source_scope == "dm" and target_scope == "dm" else None
                item["forward_name"], item["forward_date"] = from_name, from_date
                item["media_fields"] = await media_message_fields(db, item.get("media_id"))
                if target_scope == "dm":
                    await require_voice_privacy(db, target_peer, uid, item["media_fields"])
                sources.append(item)

            # Preserve albums (including a selected subset) without reusing the
            # source album identity in the destination chat.
            albums: dict[str, list[int]] = {}
            for index, item in enumerate(sources):
                album = str(item.get("media_album_id") or "")
                if album and item.get("media_id"):
                    albums.setdefault(album, []).append(index)
            album_for: dict[int, tuple[str, int, int]] = {}
            for indexes in albums.values():
                if len(indexes) > 1:
                    album_id = secrets.token_hex(16)
                    for position, index in enumerate(indexes):
                        album_for[index] = (album_id, position, len(indexes))

            created = []
            for index, item in enumerate(sources):
                media_id = item.get("media_id")
                body = "" if drop_captions and media_id else str(item["body"] or "")
                album_id, album_index, album_count = album_for.get(index, (None, 0, 0))
                if target_scope == "dm":
                    await require_free_dm(db, uid, target_peer)
                    cur = await db.execute("""INSERT INTO messages(sender_telegram_id,recipient_telegram_id,body,media_id,
                        media_album_id,media_album_index,media_album_count,created_at) VALUES(?,?,?,?,?,?,?,?)""",
                        (uid, target_peer, body, media_id, album_id, album_index, album_count, now))
                elif target_scope == "group":
                    cur = await db.execute("""INSERT INTO group_messages(group_id,sender_telegram_id,body,media_id,
                        media_album_id,media_album_index,media_album_count,created_at) VALUES(?,?,?,?,?,?,?,?)""",
                        (target_peer, uid, body, media_id, album_id, album_index, album_count, now))
                else:
                    cur = await db.execute("""INSERT INTO channel_messages(channel_id,author_telegram_id,body,media_id,
                        media_album_id,media_album_index,media_album_count,created_at) VALUES(?,?,?,?,?,?,?,?)""",
                        (target_peer, uid, body, media_id, album_id, album_index, album_count, now))
                mid = int(cur.lastrowid)
                entity_json = item.get("entities_json") or "[]"
                if drop_captions and media_id:
                    entity_json = "[]"
                target_table = {"dm": "messages", "group": "group_messages", "channel": "channel_messages"}[target_scope]
                if silent:
                    await db.execute(f"UPDATE {target_table} SET silent=1 WHERE id=?", (mid,))
                if entity_json != "[]":
                    await db.execute(f"UPDATE {target_table} SET entities_json=? WHERE id=?", (entity_json, mid))
                location = item["forward_location"]
                if location:
                    if target_scope == "dm":
                        await db.execute("INSERT INTO message_locations(message_id,latitude,longitude,label,venue_json) VALUES(?,?,?,?,?)", (mid, *location))
                    else:
                        await db.execute("INSERT INTO message_forward_locations(scope,message_id,latitude,longitude,label,venue_json) VALUES(?,?,?,?,?,?)", (target_scope, mid, *location))
                contact = item["forward_contact"]
                if contact:
                    if target_scope == "dm":
                        await db.execute("""INSERT INTO message_contacts(message_id,contact_name,contact_phone,contact_email,
                            contact_first_name,contact_last_name,contact_vcard) VALUES(?,?,?,?,?,?,?)""", (mid, *contact))
                    else:
                        await db.execute("""INSERT INTO message_scoped_contacts(scope,message_id,contact_name,contact_phone,contact_email,
                            contact_first_name,contact_last_name,contact_vcard) VALUES(?,?,?,?,?,?,?,?)""", (target_scope, mid, *contact))
                link_author = item["forward_link_author"]
                if not drop_author and link_author:
                    # Keep provenance for viewer-side checks, including later changes to privacy.
                    await db.execute("UPDATE messages SET forwarded_from_telegram_id=? WHERE id=?", (link_author, mid))
                if not drop_author:
                    await db.execute("INSERT INTO message_forward_sources(scope,message_id,from_name,from_date) VALUES(?,?,?,?)",
                                     (target_scope, mid, item["forward_name"], item["forward_date"]))
                await record_event(db, target_scope, mid, "new_message", uid,
                                   chat_id=target_peer if target_scope != "dm" else 0,
                                   user_a=uid if target_scope == "dm" else 0,
                                   user_b=target_peer if target_scope == "dm" else 0)
                result_item = {"id": mid, "body": body, "media_id": media_id, "created_at": now,
                    "media_album_id": album_id, "media_album_index": album_index, "media_album_count": album_count,
                    **item["media_fields"], "entities_json": entity_json}
                _add_message_entities(result_item)
                if location:
                    result_item.update(location_latitude=location[0], location_longitude=location[1], location_label=location[2], location_venue_json=location[3])
                if contact:
                    result_item.update(zip(("contact_name", "contact_phone", "contact_email", "contact_first_name", "contact_last_name", "contact_vcard"), contact))
                if target_scope == "dm":
                    result_item.update(sender_id=uid, recipient_id=target_peer)
                elif target_scope == "group":
                    result_item.update(group_id=target_peer, sender_id=uid)
                else:
                    result_item.update(channel_id=target_peer, author_id=uid)
                if not drop_author:
                    result_item.update(forwarded_from_display_name=item["forward_name"], forwarded_from_date=item["forward_date"])
                    if link_author and await privacy_allows(db, int(link_author), uid, "forwards"):
                        result_item["forwarded_from_telegram_id"] = link_author
                created.append(result_item)
            result = {"status": "forwarded", "messages": created, "count": len(created)}
            await idempotency_store(db, uid, scope, descriptor, result, now)
            if target_scope == "dm" and target_peer != uid and not silent:
                queued_push = await enqueue_push(db, uid, target_peer,
                    str(user.get("display_name") or user.get("username") or "Новое сообщение"),
                    "Переслано сообщений: " + str(len(created)),
                    {"scope": "dm", "chat_id": str(uid), "message_id": str(created[-1]["id"]), "silent": "1" if silent else "0"}, now)
            elif target_scope in ("group", "channel") and not silent:
                member_table, id_column = ("group_members", "group_id") if target_scope == "group" else ("active_channel_members", "channel_id")
                cur = await db.execute(f"SELECT telegram_id FROM {member_table} WHERE {id_column}=? AND telegram_id<>? LIMIT 500", (target_peer, uid))
                notifications = [int(row[0]) for row in await cur.fetchall()]
            await db.commit()
        if queued_push:
            push_wakeup.set()
        if notifications:
            await deliver_push_notifications(notifications, str(user.get("display_name") or "Новое сообщение"),
                "Переслано сообщений: " + str(len(created)),
                {"scope": target_scope, "chat_id": str(target_peer), "message_id": str(created[-1]["id"]), "silent": "1" if silent else "0"})
        return result

    @router.post("/api/messages/{message_id}/forward", status_code=201)
    async def forward_message(
        message_id: int,
        payload: dict[str, Any],
        authorization: str | None = Header(default=None),
        idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        try:
            recipient_id = int(payload.get("recipient_id", 0))
        except (TypeError, ValueError):
            recipient_id = 0
        if recipient_id <= 0:
            raise HTTPException(status_code=400, detail="Укажите корректного получателя")
        now = int(time.time())
        scope = f"/api/messages/{message_id}/forward"
        descriptor = idempotency_descriptor(scope, payload, idempotency_key)
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            await db.execute("BEGIN IMMEDIATE")
            previous = await idempotency_lookup(db, uid, scope, descriptor, now)
            if previous is not None:
                await db.rollback()
                return previous
            cur = await db.execute(
                """SELECT m.id,m.sender_telegram_id,m.recipient_telegram_id,m.body,m.media_id,m.entities_json,
                          m.forwarded_from_telegram_id,m.forwarded_from_message_id,
                          COALESCE(a.display_name,a.username,'Пользователь') AS original_sender_name
                   FROM messages m
                   LEFT JOIN accounts a
                     ON a.telegram_id=COALESCE(m.forwarded_from_telegram_id,m.sender_telegram_id)
                   WHERE m.id=? AND (m.sender_telegram_id=? OR m.recipient_telegram_id=?)
                     AND NOT EXISTS (SELECT 1 FROM message_hidden_for h
                                     WHERE h.message_id=m.id AND h.telegram_id=?)""",
                (message_id, uid, uid, uid),
            )
            source = await cur.fetchone()
            if source is None:
                await db.rollback()
                raise HTTPException(status_code=404, detail="Исходное сообщение не найдено")
            # These attachments have distinct semantics and must not be silently
            # converted to plain text or transfer a gift to an unintended recipient.
            cur = await db.execute(
                """SELECT EXISTS(SELECT 1 FROM message_gifts WHERE message_id=?)
                        OR EXISTS(SELECT 1 FROM message_contacts WHERE message_id=?)
                        OR EXISTS(SELECT 1 FROM message_locations WHERE message_id=?)""",
                (message_id, message_id, message_id),
            )
            if (await cur.fetchone())[0]:
                await db.rollback()
                raise HTTPException(status_code=400, detail="Пересылка этого типа вложения пока не поддерживается")
            cur = await db.execute(
                "SELECT is_banned FROM accounts WHERE telegram_id=?", (recipient_id,)
            )
            target = await cur.fetchone()
            if target is None:
                await db.rollback()
                raise HTTPException(status_code=404, detail="Получатель не найден")
            if target[0]:
                await db.rollback()
                raise HTTPException(status_code=403, detail="Получатель заблокирован")
            cur = await db.execute(
                """SELECT 1 FROM blocked_users
                   WHERE (owner_telegram_id=? AND blocked_telegram_id=?)
                      OR (owner_telegram_id=? AND blocked_telegram_id=?)
                   LIMIT 1""",
                (uid, recipient_id, recipient_id, uid),
            )
            if await cur.fetchone():
                await db.rollback()
                raise HTTPException(status_code=403, detail="Нельзя переслать сообщение: пользователь находится в чёрном списке")
            cur = await db.execute(
                "SELECT COUNT(*) FROM messages WHERE sender_telegram_id=? AND created_at>?",
                (uid, now - 60),
            )
            if int((await cur.fetchone())[0]) >= DM_MESSAGES_PER_MINUTE:
                await db.rollback()
                raise HTTPException(status_code=429, detail="Превышен лимит отправки сообщений")
            media_fields = await media_message_fields(db, source["media_id"])
            await require_voice_privacy(db, recipient_id, uid, media_fields)
            forwarded_from_id = (
                int(source["forwarded_from_telegram_id"])
                if source["forwarded_from_telegram_id"] is not None
                else int(source["sender_telegram_id"])
            )
            forwarded_from_message_id = (
                int(source["forwarded_from_message_id"])
                if source["forwarded_from_message_id"] is not None
                else int(source["id"])
            )
            await require_free_dm(db, uid, recipient_id)
            cur = await db.execute(
                """INSERT INTO messages
                   (sender_telegram_id,recipient_telegram_id,body,media_id,reply_to_id,created_at,
                    forwarded_from_telegram_id,forwarded_from_message_id)
                   VALUES(?,?,?,?,NULL,?,?,?)""",
                (
                    uid, recipient_id, str(source["body"]), source["media_id"], now,
                    forwarded_from_id, forwarded_from_message_id,
                ),
            )
            new_message_id = int(cur.lastrowid)
            if source["entities_json"] != "[]":
                await db.execute("UPDATE messages SET entities_json=? WHERE id=?", (source["entities_json"], new_message_id))
            await record_event(
                db, "dm", new_message_id, "new_message", uid,
                user_a=uid, user_b=recipient_id,
            )
            result = {
                "id": new_message_id,
                "status": "forwarded",
                "sender_id": uid,
                "recipient_id": recipient_id,
                "body": str(source["body"]),
                "media_id": source["media_id"],
                "forwarded_from_telegram_id": forwarded_from_id,
                "forwarded_from_message_id": forwarded_from_message_id,
                "forwarded_from_display_name": str(source["original_sender_name"] or "Пользователь"),
                "entities_json": source["entities_json"],
                **media_fields,
                "created_at": now,
            }
            if not await privacy_allows(db, forwarded_from_id, uid, "forwards"):
                result["forwarded_from_telegram_id"] = None
                result["forwarded_from_message_id"] = None
            _add_message_entities(result)
            await idempotency_store(db, uid, scope, descriptor, result, now)
            await db.commit()
        await deliver_push_notifications(
            [recipient_id],
            str(user.get("display_name") or user.get("username") or "Новое сообщение"),
            str(source["body"]),
            {"scope": "dm", "chat_id": str(uid), "message_id": str(new_message_id)},
        )
        return result

    async def record_event(
        db: Any, scope: str, message_id: int, kind: str, actor_id: int,
        chat_id: int = 0, user_a: int = 0, user_b: int = 0,
    ) -> None:
        await db.execute(
            """INSERT INTO message_events(scope,chat_id,user_a,user_b,message_id,kind,actor_id,created_at)
               VALUES(?,?,?,?,?,?,?,?)""",
            (scope, chat_id, user_a, user_b, message_id, kind, actor_id, int(time.time())),
        )

    @router.get("/api/me/auto-delete")
    async def get_default_auto_delete(authorization: str | None = Header(default=None)):
        uid = int((await current_user(authorization))["telegram_id"])
        async with aiosqlite.connect(db_path()) as db:
            cur = await db.execute("SELECT seconds FROM dm_auto_delete_defaults WHERE telegram_id=?", (uid,))
            row = await cur.fetchone()
        return {"seconds": row[0] if row else 0}

    @router.put("/api/me/auto-delete")
    async def set_default_auto_delete(payload: dict[str, Any], authorization: str | None = Header(default=None)):
        uid = int((await current_user(authorization))["telegram_id"])
        seconds = payload.get("seconds")
        if type(seconds) is not int or seconds not in (0, 86400, 604800, 2592000):
            raise HTTPException(400, "AUTO_DELETE_INVALID")
        async with aiosqlite.connect(db_path()) as db:
            if seconds:
                await db.execute("""INSERT INTO dm_auto_delete_defaults VALUES(?,?)
                    ON CONFLICT(telegram_id) DO UPDATE SET seconds=excluded.seconds""", (uid, seconds))
            else:
                await db.execute("DELETE FROM dm_auto_delete_defaults WHERE telegram_id=?", (uid,))
            await db.commit()
        return {"seconds": seconds}

    @router.get("/api/chats/{peer_id}/auto-delete")
    async def get_dm_auto_delete(peer_id: int, authorization: str | None = Header(default=None)):
        uid = int((await current_user(authorization))["telegram_id"])
        if not 0 < peer_id < 2**63 or peer_id == uid:
            raise HTTPException(400, "PEER_ID_INVALID")
        async with aiosqlite.connect(db_path()) as db:
            return {"seconds": await dm_auto_delete_seconds(db, uid, peer_id)}

    @router.put("/api/chats/{peer_id}/auto-delete")
    async def set_dm_auto_delete(peer_id: int, payload: dict[str, Any], authorization: str | None = Header(default=None)):
        uid = int((await current_user(authorization))["telegram_id"])
        seconds = payload.get("seconds")
        if not 0 < peer_id < 2**63 or peer_id == uid:
            raise HTTPException(400, "PEER_ID_INVALID")
        if type(seconds) is not int or seconds not in (0, 86400, 604800, 2592000):
            raise HTTPException(400, "AUTO_DELETE_INVALID")
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            cur = await db.execute("SELECT 1 FROM accounts WHERE telegram_id=? AND is_banned=0", (peer_id,))
            if not await cur.fetchone():
                raise HTTPException(404, "PEER_NOT_FOUND")
            cur = await db.execute("SELECT 1 FROM blocked_users WHERE (owner_telegram_id=? AND blocked_telegram_id=?) OR (owner_telegram_id=? AND blocked_telegram_id=?)", (uid, peer_id, peer_id, uid))
            if await cur.fetchone():
                raise HTTPException(403, "PEER_BLOCKED")
            pair = sorted((uid, peer_id))
            await db.execute("INSERT OR IGNORE INTO dm_auto_delete_seen VALUES(?,?)", pair)
            if seconds:
                await db.execute("""INSERT INTO dm_auto_delete VALUES(?,?,?)
                    ON CONFLICT(user_low,user_high) DO UPDATE SET seconds=excluded.seconds""", (*pair, seconds))
            else:
                await db.execute("DELETE FROM dm_auto_delete WHERE user_low=? AND user_high=?", pair)
            await db.commit()
        return {"seconds": seconds}

    async def expire_dm_messages(db: Any, now: int) -> int:
        cur = await db.execute("""SELECT id,sender_telegram_id,recipient_telegram_id FROM messages
            WHERE auto_delete_at<=? ORDER BY auto_delete_at,id LIMIT 500""", (now,))
        rows = await cur.fetchall()
        for message_id, sender, recipient in rows:
            for table in ("message_hidden_for", "message_gifts", "message_contacts", "message_locations", "dm_pin_overrides"):
                await db.execute(f"DELETE FROM {table} WHERE message_id=?", (message_id,))
            await db.execute("DELETE FROM pinned_messages WHERE scope='dm' AND chat_id=0 AND message_id=?", (message_id,))
            await db.execute("DELETE FROM messages WHERE id=?", (message_id,))
            await record_event(db, "dm", message_id, "delete", 0, user_a=sender, user_b=recipient)
        return len(rows)

    async def process_due_scheduled_messages() -> None:
        now = int(time.time())
        notifications: list[tuple[int, int, str, str, int, bool]] = []
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            cur = await db.execute(
                """SELECT id,sender_telegram_id,recipient_telegram_id,body,silent,
                          scheduled_at,repeat_interval_seconds,time_zone,entities_json
                   FROM scheduled_messages
                   WHERE status='pending' AND scheduled_at<=?
                   ORDER BY scheduled_at ASC,id ASC LIMIT 100""",
                (now,),
            )
            due = await cur.fetchall()
            for scheduled in due:
                scheduled_id, sender_id, recipient_id, body, silent, scheduled_at, repeat_interval, time_zone, entities_json = scheduled
                cur = await db.execute(
                    "SELECT is_banned FROM accounts WHERE telegram_id=?",
                    (sender_id,),
                )
                sender = await cur.fetchone()
                cur = await db.execute(
                    "SELECT is_banned FROM accounts WHERE telegram_id=?",
                    (recipient_id,),
                )
                recipient = await cur.fetchone()
                failure = ""
                if sender is None or sender[0]:
                    failure = "Аккаунт отправителя недоступен"
                elif recipient is None or recipient[0]:
                    failure = "Получатель недоступен"
                elif int(sender_id) != int(recipient_id):
                    cur = await db.execute(
                        """SELECT 1 FROM blocked_users
                           WHERE (owner_telegram_id=? AND blocked_telegram_id=?)
                              OR (owner_telegram_id=? AND blocked_telegram_id=?)
                           LIMIT 1""",
                        (sender_id, recipient_id, recipient_id, sender_id),
                    )
                    if await cur.fetchone():
                        failure = "Пользователь находится в чёрном списке"
                cur = await db.execute(
                    "SELECT COUNT(*) FROM messages WHERE sender_telegram_id=? AND created_at>?",
                    (sender_id, now - 60),
                )
                if not failure and int((await cur.fetchone())[0]) >= DM_MESSAGES_PER_MINUTE:
                    continue
                if not failure and await dm_message_fee(db, sender_id, recipient_id):
                    failure = "Для сообщения требуется подтверждение оплаты Stars"
                if failure:
                    await db.execute(
                        "UPDATE scheduled_messages SET status='failed',error=? WHERE id=? AND status='pending'",
                        (failure, scheduled_id),
                    )
                    if scheduled_id <= 1073741823:
                        await record_event(db, "scheduled", scheduled_id * 2, "scheduled_changed", int(sender_id), chat_id=int(recipient_id))
                    continue
                cur = await db.execute(
                    """INSERT INTO messages(sender_telegram_id,recipient_telegram_id,body,created_at)
                       VALUES(?,?,?,?)""",
                    (sender_id, recipient_id, body, now),
                )
                message_id = int(cur.lastrowid)
                if entities_json and entities_json != "[]":
                    await db.execute("UPDATE messages SET entities_json=? WHERE id=?", (entities_json, message_id))
                if silent:
                    await db.execute("UPDATE messages SET silent=1 WHERE id=?", (message_id,))
                await record_event(
                    db, "dm", message_id, "new_message", int(sender_id),
                    user_a=int(sender_id), user_b=int(recipient_id),
                )
                if int(repeat_interval) > 0:
                    next_scheduled_at = _next_recurring_scheduled_timestamp(
                        int(scheduled_at), now, int(repeat_interval), str(time_zone or "UTC")
                    )
                    await db.execute(
                        """UPDATE scheduled_messages
                           SET scheduled_at=?,created_at=?,message_id=?,error=''
                           WHERE id=? AND status='pending'""",
                        (next_scheduled_at, now, message_id, scheduled_id),
                    )
                else:
                    await db.execute(
                        """UPDATE scheduled_messages
                           SET status='sent',message_id=?,error=''
                           WHERE id=? AND status='pending'""",
                        (message_id, scheduled_id),
                    )
                if scheduled_id <= 1073741823:
                    await record_event(db, "scheduled", scheduled_id * 2,
                        "scheduled_changed" if int(repeat_interval) > 0 else "scheduled_removed",
                        int(sender_id), chat_id=int(recipient_id))
                notifications.append((
                    int(recipient_id), int(sender_id),
                    str(body), str(scheduled_id), message_id, bool(silent),
                ))
            await db.commit()
        for recipient_id, sender_id, body, scheduled_id, message_id, silent in notifications:
            await deliver_push_notifications(
                [recipient_id],
                "Отложенное сообщение",
                body,
                {
                    "scope": "dm",
                    "chat_id": str(sender_id),
                    "message_id": str(message_id),
                    "scheduled_message_id": scheduled_id,
                    "silent": "1" if silent else "0",
                },
            )

    async def process_messages_waiting_for_online() -> None:
        now = int(time.time())
        notifications: list[tuple[int, int, str, int, bool]] = []
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            cur = await db.execute(
                """SELECT queued.id,queued.sender_telegram_id,queued.recipient_telegram_id,
                          queued.body,queued.silent,queued.entities_json
                   FROM online_scheduled_messages queued
                   JOIN api_user_presence presence
                     ON presence.telegram_id=queued.recipient_telegram_id
                   WHERE queued.status='pending'
                     AND presence.last_seen_at>=queued.created_at
                     AND presence.last_seen_at>=?
                   ORDER BY queued.created_at,queued.id LIMIT 100""",
                (now - 45,),
            )
            due = await cur.fetchall()
            for queued in due:
                scheduled_id, sender_id, recipient_id, body, silent, entities_json = queued
                cur = await db.execute(
                    "SELECT is_banned FROM accounts WHERE telegram_id=?", (sender_id,)
                )
                sender = await cur.fetchone()
                cur = await db.execute(
                    "SELECT is_banned FROM accounts WHERE telegram_id=?", (recipient_id,)
                )
                recipient = await cur.fetchone()
                failure = ""
                if sender is None or sender[0]:
                    failure = "Аккаунт отправителя недоступен"
                elif recipient is None or recipient[0]:
                    failure = "Получатель недоступен"
                else:
                    cur = await db.execute(
                        """SELECT 1 FROM blocked_users
                           WHERE (owner_telegram_id=? AND blocked_telegram_id=?)
                              OR (owner_telegram_id=? AND blocked_telegram_id=?) LIMIT 1""",
                        (sender_id, recipient_id, recipient_id, sender_id),
                    )
                    if await cur.fetchone():
                        failure = "Пользователь находится в чёрном списке"
                if not failure and await dm_message_fee(db, sender_id, recipient_id):
                    failure = "Для сообщения требуется подтверждение оплаты Stars"
                if failure:
                    await db.execute(
                        "UPDATE online_scheduled_messages SET status='failed',error=? WHERE id=? AND status='pending'",
                        (failure, scheduled_id),
                    )
                    if scheduled_id <= 1073741823:
                        await record_event(db, "scheduled", scheduled_id * 2 + 1, "scheduled_changed", int(sender_id), chat_id=int(recipient_id))
                    continue
                cur = await db.execute(
                    "SELECT COUNT(*) FROM messages WHERE sender_telegram_id=? AND created_at>?",
                    (sender_id, now - 60),
                )
                if int((await cur.fetchone())[0]) >= DM_MESSAGES_PER_MINUTE:
                    continue
                cur = await db.execute(
                    """INSERT INTO messages(sender_telegram_id,recipient_telegram_id,body,created_at)
                       VALUES(?,?,?,?)""",
                    (sender_id, recipient_id, body, now),
                )
                message_id = int(cur.lastrowid)
                if entities_json and entities_json != "[]":
                    await db.execute("UPDATE messages SET entities_json=? WHERE id=?", (entities_json, message_id))
                if silent:
                    await db.execute("UPDATE messages SET silent=1 WHERE id=?", (message_id,))
                await record_event(
                    db, "dm", message_id, "new_message", int(sender_id),
                    user_a=int(sender_id), user_b=int(recipient_id),
                )
                await db.execute(
                    """UPDATE online_scheduled_messages
                       SET status='sent',message_id=?,error=''
                       WHERE id=? AND status='pending'""",
                    (message_id, scheduled_id),
                )
                if scheduled_id <= 1073741823:
                    await record_event(db, "scheduled", scheduled_id * 2 + 1, "scheduled_removed", int(sender_id), chat_id=int(recipient_id))
                notifications.append((int(recipient_id), int(sender_id), str(body), message_id, bool(silent)))
            await db.commit()
        for recipient_id, sender_id, body, message_id, silent in notifications:
            await deliver_push_notifications(
                [recipient_id],
                "Отложенное сообщение",
                body,
                {"scope": "dm", "chat_id": str(sender_id), "message_id": str(message_id), "silent": "1" if silent else "0"},
            )

    scheduled_worker_task: asyncio.Task | None = None

    async def scheduled_message_worker() -> None:
        last_auction_settlement = 0
        last_live_cleanup = -60.0
        last_account_cleanup = None
        while True:
            try:
                await process_due_scheduled_messages()
                await process_due_inbox_proposals()
                await process_due_channel_giveaways()
                await process_messages_waiting_for_online()
                now = int(time.time())
                if now - last_auction_settlement >= 5:
                    await process_due_collectible_auctions()
                    last_auction_settlement = now
            except Exception as exc:
                LOGGER.warning(
                    "Scheduled message or collectible auction processing failed (%s)",
                    type(exc).__name__,
                )
            # Privacy cleanup remains independent of failures in unrelated workers.
            monotonic_now = time.monotonic()
            if monotonic_now - last_live_cleanup >= 60:
                try:
                    async with aiosqlite.connect(db_path()) as db:
                        await db.execute("BEGIN IMMEDIATE")
                        count = max(await _expire_live_locations(db, int(time.time())),
                                    await expire_dm_messages(db, int(time.time())))
                        await db.commit()
                    # Continue bounded batches on the next pass when there is a backlog.
                    if count < 500:
                        last_live_cleanup = monotonic_now
                except Exception as exc:
                    LOGGER.warning("Message expiry cleanup failed (%s)", type(exc).__name__)
            if last_account_cleanup is None or monotonic_now - last_account_cleanup >= 3600:
                last_account_cleanup = monotonic_now
                try:
                    await process_inactive_accounts(int(time.time()))
                except Exception as exc:
                    LOGGER.warning("Inactive account scan failed (%s)", type(exc).__name__)
            await asyncio.sleep(1.0)

    @router.on_event("startup")
    async def start_scheduled_message_worker() -> None:
        nonlocal scheduled_worker_task
        if scheduled_worker_task is None or scheduled_worker_task.done():
            scheduled_worker_task = asyncio.create_task(scheduled_message_worker())

    @router.on_event("shutdown")
    async def stop_scheduled_message_worker() -> None:
        nonlocal scheduled_worker_task
        if scheduled_worker_task is not None:
            scheduled_worker_task.cancel()
            await asyncio.gather(scheduled_worker_task, return_exceptions=True)
            scheduled_worker_task = None

    def edited_content(payload: dict[str, Any]) -> tuple[str, list[dict[str, Any]]]:
        # Empty text clears a media caption; the message type is verified
        # within the same transaction that performs the update.
        value = payload.get("body")
        if isinstance(value, str) and not value.strip():
            if "entities" in payload and payload["entities"] != []:
                raise HTTPException(status_code=400, detail="Пустая подпись не может содержать форматирование")
            return "", []
        if "entities" in payload:
            return _message_body_and_entities(payload)
        return edited_body(payload), []

    def edited_body(payload: dict[str, Any]) -> str:
        value = payload.get("body")
        if not isinstance(value, str) or not value.strip():
            raise HTTPException(status_code=400, detail="Текст сообщения не может быть пустым")
        return _message_body(value)

    async def toggle_message_reaction(
        scope: str,
        chat_id: int,
        message_id: int,
        user_id: int,
        reaction: str,
    ) -> dict[str, Any]:
        allowed = {"👍", "❤️", "😂", "😮", "😢", "🎉", "🙏"}
        if reaction not in allowed:
            raise HTTPException(status_code=400, detail="Недопустимая реакция")
        now = int(time.time())
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            event_user_a = 0
            event_user_b = 0
            if scope == "dm":
                cur = await db.execute(
                    """SELECT sender_telegram_id,recipient_telegram_id FROM messages WHERE id=?
                       AND NOT EXISTS (SELECT 1 FROM message_hidden_for h
                                       WHERE h.message_id=messages.id AND h.telegram_id=?)""",
                    (message_id, user_id),
                )
                message = await cur.fetchone()
                if message is None or user_id not in (int(message[0]), int(message[1])):
                    await db.rollback()
                    raise HTTPException(status_code=404, detail="Сообщение не найдено")
                event_user_a = int(message[0])
                event_user_b = int(message[1])
            elif scope == "group":
                await require_group_member(db, chat_id, user_id)
                cur = await db.execute(
                    "SELECT 1 FROM group_messages WHERE id=? AND group_id=?",
                    (message_id, chat_id),
                )
                if await cur.fetchone() is None:
                    await db.rollback()
                    raise HTTPException(status_code=404, detail="Сообщение не найдено")
            elif scope == "channel":
                cur = await db.execute(
                    """SELECT NOT EXISTS(SELECT 1 FROM channel_bans cb WHERE cb.channel_id=c.id AND cb.telegram_id=? AND (cb.until_date=0 OR cb.until_date>CAST(strftime('%s','now') AS INTEGER))) AND (c.is_public=1 OR c.owner_telegram_id=?
                           OR EXISTS(SELECT 1 FROM channel_admins ca WHERE ca.channel_id=c.id AND ca.telegram_id=?)
                           OR EXISTS(SELECT 1 FROM active_channel_members cm WHERE cm.channel_id=c.id AND cm.telegram_id=?))
                       FROM channels c WHERE c.id=?""", (user_id, user_id, user_id, user_id, chat_id),
                )
                channel = await cur.fetchone()
                if channel is None:
                    raise HTTPException(status_code=404, detail="Канал не найден")
                if not channel[0]:
                    raise HTTPException(status_code=403, detail="Нет доступа к приватному каналу")
                cur = await db.execute(
                    "SELECT 1 FROM channel_messages WHERE id=? AND channel_id=?",
                    (message_id, chat_id),
                )
                if await cur.fetchone() is None:
                    await db.rollback()
                    raise HTTPException(status_code=404, detail="Публикация не найдена")
            cur = await db.execute(
                """SELECT 1 FROM message_reactions
                   WHERE scope=? AND chat_id=? AND message_id=?
                     AND user_telegram_id=? AND reaction=?""",
                (scope, chat_id, message_id, user_id, reaction),
            )
            exists = await cur.fetchone() is not None
            if exists:
                await db.execute(
                    """DELETE FROM message_reactions
                       WHERE scope=? AND chat_id=? AND message_id=?
                         AND user_telegram_id=? AND reaction=?""",
                    (scope, chat_id, message_id, user_id, reaction),
                )
                status = "removed"
            else:
                cur = await db.execute(
                    """SELECT COUNT(*) FROM message_reactions
                       WHERE scope=? AND chat_id=? AND message_id=? AND user_telegram_id=?""",
                    (scope, chat_id, message_id, user_id),
                )
                if int((await cur.fetchone())[0]) >= 3:
                    await db.rollback()
                    raise HTTPException(status_code=409, detail="Можно поставить не более трёх разных реакций")
                await db.execute(
                    """INSERT INTO message_reactions
                       (scope,chat_id,message_id,user_telegram_id,reaction,created_at)
                       VALUES(?,?,?,?,?,?)""",
                    (scope, chat_id, message_id, user_id, reaction, now),
                )
                status = "added"
            cur = await db.execute(
                """SELECT reaction,COUNT(*) AS count FROM message_reactions
                   WHERE scope=? AND chat_id=? AND message_id=?
                   GROUP BY reaction ORDER BY MIN(created_at),reaction""",
                (scope, chat_id, message_id),
            )
            summary = [{"reaction": str(row[0]), "count": int(row[1])} for row in await cur.fetchall()]
            cur = await db.execute(
                """SELECT reaction FROM message_reactions
                   WHERE scope=? AND chat_id=? AND message_id=? AND user_telegram_id=?
                   ORDER BY created_at,reaction""",
                (scope, chat_id, message_id, user_id),
            )
            mine = [str(row[0]) for row in await cur.fetchall()]
            await record_event(
                db,
                scope,
                message_id,
                "reaction",
                user_id,
                chat_id=chat_id,
                user_a=event_user_a,
                user_b=event_user_b,
            )
            await db.commit()
        return {
            "status": status,
            "scope": scope,
            "chat_id": chat_id,
            "message_id": message_id,
            "reactions": summary,
            "my_reactions": mine,
        }

    async def set_message_reactions(
        scope: str, chat_id: int, message_id: int, user_id: int,
        requested: Any, peer_id: Any = None, extended: bool = False, big: Any = False,
    ) -> dict[str, Any]:
        """Atomically replace this account's emoji set, never toggle on retry."""
        basic = {"👍", "❤️", "😂", "😮", "😢", "🎉", "🙏"}
        allowed = {"👍", "❤️", "😂", "😮", "😢", "🎉", "🙏", "👎", "🔥", "🥰", "👏", "😁", "🤔", "🤯", "😱", "🤬", "😡", "🤩", "😎", "💯", "❤️‍🔥", "💔", "💩", "🤮", "🤝", "👀", "🙌", "😍", "🥳", "😭", "😘", "🤣", "🤗", "🫡", "🕊️", "⚡", "🏆", "🍾", "🎄", "🤡"} if extended else basic
        if not isinstance(requested, list) or len(requested) > 3:
            raise HTTPException(status_code=400, detail="Можно выбрать не более трёх реакций")
        if not isinstance(big, bool) or (big and len(requested) != 1):
            raise HTTPException(status_code=400, detail="Большая анимация доступна для одной реакции")
        if any(not isinstance(value, str) or value not in allowed for value in requested) or len(set(requested)) != len(requested):
            raise HTTPException(status_code=400, detail="Недопустимый набор реакций")
        if not 0 < message_id <= 9223372036854775807 or (
            scope == "dm" and (isinstance(peer_id, bool) or not isinstance(peer_id, int)
                               or not 0 < peer_id <= 9223372036854775807)
        ) or (scope != "dm" and not 0 < chat_id <= 9223372036854775807):
            raise HTTPException(status_code=400, detail="Некорректные параметры сообщения")
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            event_a = event_b = 0
            if scope == "dm":
                cur = await db.execute(
                    """SELECT sender_telegram_id,recipient_telegram_id FROM messages
                       WHERE id=? AND ((sender_telegram_id=? AND recipient_telegram_id=?)
                                      OR (sender_telegram_id=? AND recipient_telegram_id=?))
                       AND NOT EXISTS (SELECT 1 FROM message_hidden_for h
                                       WHERE h.message_id=messages.id AND h.telegram_id=?)""",
                    (message_id, user_id, peer_id, peer_id, user_id, user_id),
                )
                message = await cur.fetchone()
                if message is None:
                    raise HTTPException(status_code=404, detail="Сообщение не найдено")
                event_a, event_b = int(message[0]), int(message[1])
            elif scope == "group":
                await require_group_member(db, chat_id, user_id)
                cur = await db.execute("SELECT 1 FROM group_messages WHERE group_id=? AND id=?", (chat_id, message_id))
                if await cur.fetchone() is None:
                    raise HTTPException(status_code=404, detail="Сообщение не найдено")
            elif scope == "channel":
                cur = await db.execute(
                    """SELECT NOT EXISTS(SELECT 1 FROM channel_bans cb WHERE cb.channel_id=c.id AND cb.telegram_id=? AND (cb.until_date=0 OR cb.until_date>CAST(strftime('%s','now') AS INTEGER))) AND (c.is_public=1 OR c.owner_telegram_id=?
                           OR EXISTS(SELECT 1 FROM channel_admins ca WHERE ca.channel_id=c.id AND ca.telegram_id=?)
                           OR EXISTS(SELECT 1 FROM active_channel_members cm WHERE cm.channel_id=c.id AND cm.telegram_id=?))
                       FROM channels c WHERE c.id=?""", (user_id, user_id, user_id, user_id, chat_id),
                )
                channel = await cur.fetchone()
                if channel is None:
                    raise HTTPException(status_code=404, detail="Канал не найден")
                if not channel[0]:
                    raise HTTPException(status_code=403, detail="Нет доступа к приватному каналу")
                cur = await db.execute("SELECT 1 FROM channel_messages WHERE channel_id=? AND id=?", (chat_id, message_id))
                if await cur.fetchone() is None:
                    raise HTTPException(status_code=404, detail="Публикация не найдена")
            else:
                raise HTTPException(status_code=400, detail="Недопустимый тип чата")
            cur = await db.execute(
                """SELECT reaction FROM message_reactions WHERE scope=? AND chat_id=? AND message_id=?
                   AND user_telegram_id=? ORDER BY created_at,reaction""", (scope, chat_id, message_id, user_id),
            )
            previous = {str(row[0]) for row in await cur.fetchall()}
            # Older clients cannot display extended choices and would otherwise
            # unintentionally erase them when replacing their own reaction set.
            if not extended and previous - basic:
                raise HTTPException(status_code=409, detail="Обновите приложение для изменения расширенных реакций")
            desired = set(requested)
            changed = previous != desired
            recent_reactions: list[dict[str, Any]] = []
            if changed:
                now = int(time.time())
                newly_added = desired - previous
                if big and len(newly_added) == 1:
                    value = next(iter(newly_added))
                    recent_reactions.append({
                        "user_id": user_id, "reaction": value,
                        "big": True, "unread": True, "date": now,
                    })
                for value in previous - desired:
                    await db.execute("""DELETE FROM message_reactions WHERE scope=? AND chat_id=? AND message_id=?
                                        AND user_telegram_id=? AND reaction=?""", (scope, chat_id, message_id, user_id, value))
                for value in requested:
                    if value not in previous:
                        await db.execute("""INSERT INTO message_reactions(scope,chat_id,message_id,user_telegram_id,reaction,created_at)
                                            VALUES(?,?,?,?,?,?)""", (scope, chat_id, message_id, user_id, value, now))
                await record_event(db, scope, message_id, "reaction", user_id, chat_id=chat_id,
                                   user_a=event_a, user_b=event_b)
            cur = await db.execute("""SELECT reaction,COUNT(*) FROM message_reactions
                    WHERE scope=? AND chat_id=? AND message_id=? GROUP BY reaction ORDER BY MIN(created_at),reaction""",
                    (scope, chat_id, message_id))
            summary = [{"reaction": str(row[0]), "count": int(row[1])} for row in await cur.fetchall()]
            cur = await db.execute("""SELECT reaction FROM message_reactions WHERE scope=? AND chat_id=? AND message_id=?
                    AND user_telegram_id=? ORDER BY created_at,reaction""", (scope, chat_id, message_id, user_id))
            mine = [str(row[0]) for row in await cur.fetchall()]
            await db.commit()
        return {"status": "updated" if changed else "unchanged", "scope": scope, "chat_id": chat_id,
                "message_id": message_id, "reactions": summary, "my_reactions": mine,
                "recent_reactions": recent_reactions}

    async def change_pinned_message(
        scope: str, chat_id: int, message_id: int, user_id: int, pin: bool,
        one_side: bool = False, notify: bool = False,
    ) -> dict[str, Any]:
        if scope not in ("dm", "group", "channel") or chat_id <= 0 or message_id <= 0:
            raise HTTPException(status_code=400, detail="Некорректные параметры закрепления")
        if one_side and scope != "dm":
            raise HTTPException(status_code=400, detail="Личное закрепление доступно только в ЛС")
        now = int(time.time())
        async with aiosqlite.connect(db_path()) as db:
            db.row_factory = aiosqlite.Row
            await db.execute("BEGIN IMMEDIATE")
            event_user_a = 0
            event_user_b = 0
            if scope == "dm":
                cur = await db.execute(
                    """SELECT sender_telegram_id,recipient_telegram_id FROM messages
                       WHERE id=? AND ((sender_telegram_id=? AND recipient_telegram_id=?)
                                      OR (sender_telegram_id=? AND recipient_telegram_id=?))
                         AND NOT EXISTS (SELECT 1 FROM message_hidden_for h
                                         WHERE h.message_id=messages.id AND h.telegram_id=?)""",
                    (message_id, user_id, chat_id, chat_id, user_id, user_id),
                )
                message = await cur.fetchone()
                if message is None:
                    await db.rollback()
                    raise HTTPException(status_code=404, detail="Сообщение не найдено в этой переписке")
                event_user_a = int(message["sender_telegram_id"])
                event_user_b = int(message["recipient_telegram_id"])
            elif scope == "group":
                membership = await require_group_member(db, chat_id, user_id)
                if not group_has_right(membership, 8):
                    await db.rollback()
                    raise HTTPException(status_code=403, detail="Закреплять сообщения могут только администраторы группы")
                cur = await db.execute(
                    "SELECT 1 FROM group_messages WHERE id=? AND group_id=? AND topic_id IS NULL", (message_id, chat_id)
                )
                if await cur.fetchone() is None:
                    await db.rollback()
                    raise HTTPException(status_code=404, detail="Сообщение группы не найдено")
            else:
                cur = await db.execute(
                    """SELECT ch.owner_telegram_id,
                              EXISTS(SELECT 1 FROM channel_admins ca
                                     WHERE ca.channel_id=ch.id AND ca.telegram_id=? AND (rights & 8) != 0) AS is_admin
                       FROM channels ch WHERE ch.id=?""",
                    (user_id, chat_id),
                )
                channel = await cur.fetchone()
                if channel is None:
                    await db.rollback()
                    raise HTTPException(status_code=404, detail="Канал не найден")
                if int(channel["owner_telegram_id"]) != user_id and not bool(channel["is_admin"]):
                    await db.rollback()
                    raise HTTPException(status_code=403, detail="Закреплять публикации могут только администраторы канала")
                cur = await db.execute(
                    "SELECT 1 FROM channel_messages WHERE id=? AND channel_id=?", (message_id, chat_id)
                )
                if await cur.fetchone() is None:
                    await db.rollback()
                    raise HTTPException(status_code=404, detail="Публикация не найдена")
            stored_chat_id = chat_id if scope != "dm" else 0
            if one_side:
                cur = await db.execute(
                    """SELECT COALESCE((SELECT is_pinned FROM dm_pin_overrides
                                         WHERE message_id=? AND user_telegram_id=?),
                                        EXISTS(SELECT 1 FROM pinned_messages
                                               WHERE scope='dm' AND chat_id=0 AND message_id=?))""",
                    (message_id, user_id, message_id),
                )
                was_pinned = bool((await cur.fetchone())[0])
                changed = was_pinned != pin
                if changed:
                    await db.execute(
                        """INSERT INTO dm_pin_overrides(message_id,user_telegram_id,is_pinned,updated_at)
                           VALUES(?,?,?,?) ON CONFLICT(message_id,user_telegram_id)
                           DO UPDATE SET is_pinned=excluded.is_pinned,updated_at=excluded.updated_at""",
                        (message_id, user_id, int(pin), now),
                    )
                status = ("pinned" if changed else "already_pinned") if pin else ("unpinned" if changed else "not_pinned")
                event_kind = ("pin_local" if pin else "unpin_local") if changed else ""
            else:
                if pin:
                    cur = await db.execute(
                        """INSERT OR IGNORE INTO pinned_messages(scope,chat_id,message_id,pinned_by,created_at)
                           VALUES(?,?,?,?,?)""",
                        (scope, stored_chat_id, message_id, user_id, now),
                    )
                else:
                    cur = await db.execute(
                        "DELETE FROM pinned_messages WHERE scope=? AND chat_id=? AND message_id=?",
                        (scope, stored_chat_id, message_id),
                    )
                shared_changed = cur.rowcount == 1
                changed = shared_changed
                event_kind = ("pin" if pin else "unpin") if shared_changed else ""
                if scope == "dm":
                    if pin:
                        # A shared pin removes hidden overrides but preserves
                        # each participant's independent personal pin.
                        cur = await db.execute("DELETE FROM dm_pin_overrides WHERE message_id=? AND is_pinned=0", (message_id,))
                        if cur.rowcount:
                            changed = True
                            event_kind = "pin"
                    else:
                        # Removing only an actor's private pin is a private
                        # event, not evidence to the peer of that pin's existence.
                        cur = await db.execute("DELETE FROM dm_pin_overrides WHERE message_id=? AND user_telegram_id=? AND is_pinned=1", (message_id, user_id))
                        if cur.rowcount:
                            changed = True
                            if not shared_changed:
                                event_kind = "unpin_local"
                        await db.execute("DELETE FROM dm_pin_overrides WHERE message_id=? AND is_pinned=0", (message_id,))
                status = ("pinned" if changed else "already_pinned") if pin else ("unpinned" if changed else "not_pinned")
            if event_kind:
                await record_event(
                    db, scope, message_id, event_kind, user_id,
                    chat_id=stored_chat_id, user_a=event_user_a, user_b=event_user_b,
                )
            await db.commit()
        if event_kind == "pin" and notify and not one_side:
            async with aiosqlite.connect(db_path()) as notify_db:
                if scope == "dm":
                    cur = await notify_db.execute(
                        """SELECT telegram_id FROM accounts WHERE telegram_id=? AND telegram_id<>?
                           AND NOT EXISTS(SELECT 1 FROM message_hidden_for WHERE message_id=? AND telegram_id=?)""",
                        (chat_id, user_id, message_id, chat_id))
                elif scope == "group":
                    cur = await notify_db.execute("SELECT telegram_id FROM group_members WHERE group_id=? AND telegram_id<>?", (chat_id, user_id))
                else:
                    cur = await notify_db.execute("SELECT telegram_id FROM active_channel_members WHERE channel_id=? AND telegram_id<>?", (chat_id, user_id))
                recipients = [int(row[0]) for row in await cur.fetchall()]
            await deliver_push_notifications(recipients, "WaysGram", "Закреплено сообщение",
                                             {"scope": scope, "chat_id": str(user_id if scope == "dm" else chat_id),
                                              "message_id": str(message_id), "event": "pin"})
        return {"status": status, "scope": scope, "peer_id": chat_id, "message_id": message_id}

