    @router.put("/api/messages/{message_id}")
    @router.patch("/api/messages/{message_id}")
    async def edit_message(
        message_id: int,
        payload: dict[str, Any],
        authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        body, entities = edited_content(payload)
        now = int(time.time())
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            cur = await db.execute(
                "SELECT sender_telegram_id,recipient_telegram_id,media_id FROM messages WHERE id=?", (message_id,)
            )
            row = await cur.fetchone()
            if row is None:
                await db.rollback()
                raise HTTPException(status_code=404, detail="Сообщение не найдено")
            if int(row[0]) != uid:
                await db.rollback()
                raise HTTPException(status_code=403, detail="Изменять можно только свои сообщения")
            if not body and not row[2]:
                raise HTTPException(status_code=400, detail="Текст сообщения не может быть пустым")
            if "entities" not in payload:
                cur = await db.execute("SELECT entities_json FROM messages WHERE id=?", (message_id,))
                if (await cur.fetchone())[0] != "[]":
                    raise HTTPException(status_code=409, detail="Укажите entities, чтобы не потерять форматирование")
            if entities:
                cur = await db.execute("SELECT EXISTS(SELECT 1 FROM message_contacts WHERE message_id=?) OR EXISTS(SELECT 1 FROM message_locations WHERE message_id=?) OR EXISTS(SELECT 1 FROM message_gifts WHERE message_id=?) FROM messages WHERE id=?", (message_id, message_id, message_id, message_id))
                if (await cur.fetchone())[0]:
                    raise HTTPException(status_code=400, detail="Форматирование вложений пока не поддерживается")
            await db.execute("UPDATE messages SET body=?,edited_at=?,entities_json=? WHERE id=?", (body, now, _message_entities_json(entities), message_id))
            await record_event(db, "dm", message_id, "edit", uid, user_a=int(row[0]), user_b=int(row[1]))
            await db.commit()
        result = {"id": message_id, "body": body, "edited_at": now}
        if entities:
            result["entities"] = entities
        return result

    @router.delete("/api/messages/{message_id}")
    async def delete_message(
        message_id: int,
        delete_for: str = Query(default="all", alias="for"),
        authorization: str | None = Header(default=None),
    ) -> dict[str, Any]:
        user = await current_user(authorization)
        uid = int(user["telegram_id"])
        if delete_for not in ("me", "all"):
            raise HTTPException(status_code=400, detail="for должен быть me или all")
        now = int(time.time())
        async with aiosqlite.connect(db_path()) as db:
            await db.execute("BEGIN IMMEDIATE")
            cur = await db.execute(
                "SELECT sender_telegram_id,recipient_telegram_id FROM messages WHERE id=?",
                (message_id,),
            )
            row = await cur.fetchone()
            if row is None:
                await db.rollback()
                raise HTTPException(status_code=404, detail="Сообщение не найдено")
            sender_id, recipient_id = int(row[0]), int(row[1])
            if uid not in (sender_id, recipient_id):
                await db.rollback()
                raise HTTPException(status_code=404, detail="Сообщение не найдено")
            if delete_for == "me":
                await db.execute(
                    """INSERT OR IGNORE INTO message_hidden_for(message_id,telegram_id,hidden_at)
                       VALUES(?,?,?)""",
                    (message_id, uid, now),
                )
                await record_event(
                    db, "dm", message_id, "delete_for_me", uid,
                    user_a=sender_id, user_b=recipient_id,
                )
                await db.commit()
                return {"id": message_id, "status": "hidden_for_me"}
            await db.execute("DELETE FROM dm_pin_overrides WHERE message_id=?", (message_id,))
            await db.execute("DELETE FROM pinned_messages WHERE scope='dm' AND chat_id=0 AND message_id=?", (message_id,))
            await db.execute("DELETE FROM messages WHERE id=?", (message_id,))
            await record_event(
                db, "dm", message_id, "delete", uid,
                user_a=sender_id, user_b=recipient_id,
            )
            await db.commit()
        return {"id": message_id, "status": "deleted_for_all"}

